void look_28(inout Look k) {
  p_rmColour = texelFetch(lookSettings, ivec2(0, 28), 0).rgb;
  p_rmWorn = texelFetch(lookSettings, ivec2(1, 28), 0).rgb;
  p_rmDirt = texelFetch(lookSettings, ivec2(2, 28), 0).rgb;
  p_rmDirtAmount = texelFetch(lookSettings, ivec2(3, 28), 0).r;
  p_rmRibs = texelFetch(lookSettings, ivec2(4, 28), 0).r;
  p_rmDepth = texelFetch(lookSettings, ivec2(5, 28), 0).r;
  p_rmRough = texelFetch(lookSettings, ivec2(6, 28), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float rmSee = kfade(2.0 / p_rmRibs);
    float rmT = fract(uv.y * p_rmRibs);
    float rmRib = smoothstep(0.15, 0.3, rmT) * (1.0 - smoothstep(0.7, 0.85, rmT));
    float rmR = mix(0.5, rmRib, rmSee);
    float rmD = p_rmDirtAmount * (1.0 - rmR) * smoothstep(0.3, 0.8, kfbm4(uv * 5.0 + seed));
    k.colour = mix(p_rmColour, p_rmWorn, rmR * 0.6 * kfbm4(uv * 12.0 + seed + 3.0));
    k.colour = mix(k.colour, p_rmDirt, clamp(rmD * 1.6, 0.0, 1.0));
    k.rough = clamp(p_rmRough - 0.15 * rmR + 0.1 * rmD, 0.0, 1.0);
    k.height = p_rmDepth * rmR;

}

void look_29(inout Look k) {
  p_plColour = texelFetch(lookSettings, ivec2(0, 29), 0).rgb;
