  p_plRelief = texelFetch(lookSettings, ivec2(2, 29), 0).r;
  p_plRough = texelFetch(lookSettings, ivec2(3, 29), 0).r;
  p_plRoughVar = texelFetch(lookSettings, ivec2(4, 29), 0).r;
  p_plTone = texelFetch(lookSettings, ivec2(5, 29), 0).r;
  p_plThrough = texelFetch(lookSettings, ivec2(6, 29), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float plS = kn(uv * p_plStipple + seed) * kfade(2.0 / p_plStipple);
    float plS2 = kn(uv * p_plStipple * 0.37 + seed + 9.0) * kfade(5.0 / p_plStipple);
    float plW = kfbm4(uv * 3.0 + seed);
    k.colour = p_plColour * (1.0 + p_plTone * (plW - 0.5) * 2.0);
    k.rough = clamp(p_plRough + p_plRoughVar * (plW - 0.5) * 2.0 + 0.05 * plS, 0.0, 1.0);
    k.height = p_plRelief * (0.6 * plS + 0.4 * plS2);
    if (p_plThrough > 0.0) {
      float plFace = clamp(abs(dot(normalize(cameraPosition - wp), normalize(wn))), 0.0, 1.0);
      k.glow = p_plThrough * k.colour * (0.45 + 0.55 * plFace) * (0.9 + 0.2 * plW);
    }

}

void look_30(inout Look k) {
  p_lpColour = texelFetch(lookSettings, ivec2(0, 30), 0).rgb;
  p_lpBack = texelFetch(lookSettings, ivec2(1, 30), 0).rgb;
  p_lpReflector = texelFetch(lookSettings, ivec2(2, 30), 0).r;
  p_lpCellW = texelFetch(lookSettings, ivec2(3, 30), 0).r;
  p_lpCellH = texelFetch(lookSettings, ivec2(4, 30), 0).r;
  p_lpFlute = texelFetch(lookSettings, ivec2(5, 30), 0).r;
  p_lpDepth = texelFetch(lookSettings, ivec2(6, 30), 0).r;
  p_lpTwinkle = texelFetch(lookSettings, ivec2(7, 30), 0).r;
  p_lpGlow = texelFetch(lookSettings, ivec2(8, 30), 0).rgb;
  p_lpSpot = texelFetch(lookSettings, ivec2(9, 30), 0).r;
  p_lpSpotSize = texelFetch(lookSettings, ivec2(10, 30), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 lpQ = uv / vec2(p_lpCellW, p_lpCellH);
    vec2 lpId = floor(lpQ);
    vec2 lpF = fract(lpQ) - 0.5;
    // the prisms seen only where one is bigger than a pixel; under that, their mean
    float lpSee = kfade(min(p_lpCellW, p_lpCellH) * 1.5);
    // each prism's swell: 1 in its middle, 0 at its rim; a flute swells across only
    float lpAcross = 1.0 - 4.0 * lpF.x * lpF.x;
    float lpUp = mix(1.0 - 4.0 * lpF.y * lpF.y, 1.0, p_lpFlute);
    float lpBump = lpAcross * lpUp;
