    rbP *= kfade(6.0 / p_rbGrit);
    float rbB = smoothstep(0.35, 0.8, kfbm4(uv * 4.0 + seed)) * p_rbBloomAmount;
    k.colour = mix(p_rbColour, p_rbBloom, rbB) * (0.95 + 0.1 * rbG) * (1.0 - 0.3 * rbP);
    k.rough = clamp(p_rbRough + 0.08 * rbB + 0.05 * rbG, 0.0, 1.0);
    k.height = p_rbRelief * (rbG - 0.6 * rbP);
    k.sheen = p_rbSheen;
    k.sheenRough = p_rbSheenRough;

}

void look_97(inout Look k) {
  p_bmColour = texelFetch(lookSettings, ivec2(0, 97), 0).rgb;
  p_bmLines = texelFetch(lookSettings, ivec2(1, 97), 0).r;
  p_bmStreak = texelFetch(lookSettings, ivec2(2, 97), 0).r;
  p_bmLong = texelFetch(lookSettings, ivec2(3, 97), 0).r;
  p_bmRough = texelFetch(lookSettings, ivec2(4, 97), 0).r;
  p_bmMetal = texelFetch(lookSettings, ivec2(5, 97), 0).r;
  p_bmRelief = texelFetch(lookSettings, ivec2(6, 97), 0).r;
  p_bmMirror = texelFetch(lookSettings, ivec2(7, 97), 0).r;
  p_bmSky = texelFetch(lookSettings, ivec2(8, 97), 0).rgb;
  p_bmWall = texelFetch(lookSettings, ivec2(9, 97), 0).rgb;
  p_bmFloor = texelFetch(lookSettings, ivec2(10, 97), 0).rgb;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 bmG = dot(s3, s3) > 0.25 ? normalize(s3) : vec2(1.0, 0.0);
    // along the brushing, across it
    vec2 bmQ = vec2(dot(uv, bmG), dot(uv, vec2(-bmG.y, bmG.x)));
    // the scratches: noise stretched far along the brushing, one row a scratch, faded to its mean where a scratch is
    // under a pixel; a few deeper, longer ones over them
    float bmFine = mix(0.5, kn(vec2(bmQ.x * p_bmLong * 4.0, bmQ.y * p_bmLines) + seed), kfade(2.0 / p_bmLines));
    float bmDeep = mix(0.5, kn(vec2(bmQ.x * p_bmLong, bmQ.y * p_bmLines * 0.18) + seed + 17.0), kfade(8.0 / p_bmLines));
    float bmS = 0.75 * bmFine + 0.25 * smoothstep(0.35, 0.8, bmDeep);
    // a slow cloud of the belt's passes, so a big sheet isn't one flat grey
    float bmPass = kfbm4(vec2(bmQ.x * 0.6, bmQ.y * 7.0) + seed * 1.3);
    vec3 bmC = p_bmColour * (1.0 + p_bmStreak * (bmS - 0.5) * 0.9) * (0.94 + 0.12 * bmPass);
    k.colour = bmC;
    k.metal = p_bmMetal;
    k.rough = clamp(p_bmRough + 0.12 * (bmS - 0.5) + 0.05 * (bmPass - 0.5), 0.03, 1.0);
    k.height = p_bmRelief * (bmS - 0.5);
    // the room mirrored, smeared along the brushing: its ray tipped across the scratches by each one's slope
    vec3 bmV = normalize(wp - cameraPosition);
    vec3 bmN = normalize(wn);
    vec3 bmR = reflect(bmV, bmN);
    float bmCos = clamp(dot(-bmV, bmN), 0.0, 1.0);
    float bmFres = 0.7 + 0.3 * pow(1.0 - bmCos, 3.0);
    vec3 bmRoom = rmRoom(normalize(bmR + 0.08 * (bmS - 0.5) * vec3(1.0, 0.0, 1.0)), clamp(p_bmRough * 2.2, 0.0, 1.0), p_bmSky, p_bmWall, p_bmFloor);
    k.glow = p_bmMirror * bmRoom * bmC * bmFres * (0.85 + 0.3 * bmS);
    if (lookView > 0.5 && lookView < 1.5) k.colour = vec3(0.5 + 0.5 * bmG.x, 0.5 + 0.5 * bmG.y, 0.5);

}

void look_98(inout Look k) {
  p_fcColour = texelFetch(lookSettings, ivec2(0, 98), 0).rgb;
  p_fcCells = texelFetch(lookSettings, ivec2(1, 98), 0).r;
  p_fcFine = texelFetch(lookSettings, ivec2(2, 98), 0).r;
  p_fcDepth = texelFetch(lookSettings, ivec2(3, 98), 0).r;
  p_fcFineDepth = texelFetch(lookSettings, ivec2(4, 98), 0).r;
  p_fcTone = texelFetch(lookSettings, ivec2(5, 98), 0).r;
  p_fcMetal = texelFetch(lookSettings, ivec2(6, 98), 0).r;
  p_fcRough = texelFetch(lookSettings, ivec2(7, 98), 0).r;
  p_fcSeam = texelFetch(lookSettings, ivec2(8, 98), 0).r;
  p_fcTape = texelFetch(lookSettings, ivec2(9, 98), 0).r;
  p_fcDust = texelFetch(lookSettings, ivec2(10, 98), 0).r;
  p_fcDustColour = texelFetch(lookSettings, ivec2(11, 98), 0).rgb;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the creased facets: a pit in each cell, its rim the creases; and the finer crumple over it
    float fcId, fcEdge, fcId2, fcEdge2;
    vec2 fcP = uv * p_fcCells + seed * 13.0;
    float fcD = kvor(fcP, fcId, fcEdge);
    float fcD2 = kvor(fcP * p_fcFine + 5.1, fcId2, fcEdge2);
    float fcF = kfade(1.0 / p_fcCells), fcF2 = kfade(1.0 / (p_fcCells * p_fcFine));
    float fcH = (fcD * (0.6 + 0.8 * fcId) - 0.5) * fcF + p_fcFineDepth * (fcD2 - 0.5) * fcF2;
    // the tape over each seam, flat and duller
    float fcS = abs(fract(uv.y / p_fcSeam + 0.5) - 0.5) * p_fcSeam;
    float fcT = (1.0 - smoothstep(p_fcTape * 0.5 - 0.001, p_fcTape * 0.5, fcS)) * kfade(p_fcTape);
    float fcTone = 1.0 + p_fcTone * (fcId - 0.5) * 2.0 * fcF;
    vec3 fcC = p_fcColour * fcTone;
    fcC = mix(fcC, p_fcColour * 0.85, fcT);
    // dust: settled in a slow cloud, thicker in the pits
    float fcDu = clamp(p_fcDust * (0.5 + kfbm4(uv * 3.0 + seed + 2.0)) * (0.8 + 0.4 * fcD * fcF), 0.0, 1.0);
    k.colour = mix(fcC, p_fcDustColour, fcDu * 0.7);
    k.metal = mix(p_fcMetal, 0.0, fcDu * 0.7);
    k.rough = clamp(mix(p_fcRough + 0.08 * fcId2 * fcF2, 0.35, fcT) + fcDu * 0.6, 0.02, 1.0);
    k.height = p_fcDepth * fcH * (1.0 - fcT);

}

void look_99(inout Look k) {
  p_pmColour = texelFetch(lookSettings, ivec2(0, 99), 0).rgb;
