void look_103(inout Look k) {
  p_ckCarbon = texelFetch(lookSettings, ivec2(0, 103), 0).rgb;
  p_ckCarbonShine = texelFetch(lookSettings, ivec2(1, 103), 0).rgb;
  p_ckAramid = texelFetch(lookSettings, ivec2(2, 103), 0).rgb;
  p_ckAramidShine = texelFetch(lookSettings, ivec2(3, 103), 0).rgb;
  p_ckTow = texelFetch(lookSettings, ivec2(4, 103), 0).r;
  p_ckMix = texelFetch(lookSettings, ivec2(5, 103), 0).r;
  p_ckFilaments = texelFetch(lookSettings, ivec2(6, 103), 0).r;
  p_ckAniso = texelFetch(lookSettings, ivec2(7, 103), 0).r;
  p_ckRelief = texelFetch(lookSettings, ivec2(8, 103), 0).r;
  p_ckRough = texelFetch(lookSettings, ivec2(9, 103), 0).r;
  p_ckCoat = texelFetch(lookSettings, ivec2(10, 103), 0).r;
  p_ckCoatRough = texelFetch(lookSettings, ivec2(11, 103), 0).r;
  p_ckMottle = texelFetch(lookSettings, ivec2(12, 103), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 ckQ = uv / p_ckTow;
    vec2 ckCell = floor(ckQ);
    vec2 ckF = fract(ckQ);
    // 2/2 twill: the warp (along v, tow number ckCell.x) floats over the weft for two rows, then under it for two,
    // stepping one each row
    float ckPhase = mod(ckCell.x + ckCell.y, 4.0);
    float ckWarpUp = step(ckPhase, 1.5);
    // across the tow on top (0 to 1) and along its float (0 at one end, 1 at the other)
    float ckAcross = mix(ckF.y, ckF.x, ckWarpUp);
    float ckAlong = mix((ckPhase - 2.0 + ckF.x) * 0.5, (ckPhase + ckF.y) * 0.5, ckWarpUp);
    float ckN = mix(ckCell.y, ckCell.x, ckWarpUp);
    float ckYarnTop = ckYarn(ckN, ckWarpUp, p_ckMix);
    // the tow's crown: flat on top, rolling down at its edges and diving at its float's ends
    float ckEdge = smoothstep(0.0, 0.1, ckAcross) * smoothstep(0.0, 0.1, 1.0 - ckAcross);
    float ckEnds = smoothstep(0.0, 0.07, ckAlong) * smoothstep(0.0, 0.07, 1.0 - ckAlong);
    float ckCrown = ckEdge * ckEnds;
    // the filaments: fine lines along the tow, faded out finer than a pixel
    float ckFilF = kfade(p_ckTow / max(p_ckFilaments, 1.0) * 2.0);
    float ckFil = 0.5 + 0.5 * sin(ckAcross * p_ckFilaments * 6.2831853 + kh(vec2(ckN, seed)) * 6.28);
    ckFil = mix(0.5, ckFil * (0.8 + 0.4 * kn(vec2(ckAlong * 6.0, ckAcross * p_ckFilaments) + ckN)), ckFilF);
    // the tow's way in the view, from the uv's change across the pixel, and how square it lies to the line of sight
    vec3 ckP = -vViewPosition;
    vec3 ckDx = dFdx(ckP), ckDy = dFdy(ckP);
    vec2 ckUx = dFdx(uv), ckUy = dFdy(uv);
    float ckDet = ckUx.x * ckUy.y - ckUx.y * ckUy.x;
    float ckS = abs(ckDet) > 1e-14 ? 1.0 / ckDet : 0.0;
    vec3 ckTu = (ckDx * ckUy.y - ckDy * ckUx.y) * ckS;
    vec3 ckTv = (ckDy * ckUx.x - ckDx * ckUy.x) * ckS;
    vec3 ckWay = normalize(mix(ckTu, ckTv, ckWarpUp) + vec3(1e-9));
    vec3 ckEye = normalize(ckP);
    // square to the eye its filaments light up, along it they go dark: a carbon twill's chequer turning over
    float ckSquare = 1.0 - abs(dot(ckEye, ckWay));
    float ckLit = mix(1.0 - p_ckAniso, 1.0, ckSquare * ckSquare);
    vec3 ckBase = ckYarnTop > 0.5 ? p_ckAramid : p_ckCarbon;
    vec3 ckShine = ckYarnTop > 0.5 ? p_ckAramidShine : p_ckCarbonShine;
    vec3 ckCol = ckBase * (0.85 + 0.3 * ckFil) + ckShine * ckLit * ckCrown * (0.7 + 0.6 * ckFil);
    // where the tow dives under its neighbour, the gap between them in the resin's shadow
    ckCol *= mix(0.55, 1.0, ckCrown);
    // finer than a pixel: the cloth's mean, its share of aramid by the mix
    float ckF2 = kfade(p_ckTow * 1.5);
    float ckShare = p_ckMix < 0.5 ? 0.0 : 0.5;
    vec3 ckMean = mix(p_ckCarbon + p_ckCarbonShine * 0.45, p_ckAramid + p_ckAramidShine * 0.45, ckShare) * 0.8;
    ckCol = mix(ckMean, ckCol, ckF2);
    // the resin: a little uneven over the tub, thicker and glossier in patches, the cloth a shade darker under it
    float ckMot = kfbm4(uv * 3.0 + seed * 7.0);
    ckCol *= 1.0 - p_ckMottle * 0.25 * (ckMot - 0.5);
    k.colour = ckCol;
    k.metal = 0.0;
    k.rough = mix(p_ckRough, p_ckRough + 0.15, ckYarnTop);
    k.height = p_ckRelief * mix(0.5, ckCrown * (0.9 + 0.1 * ckFil), ckF2);
    k.ao = mix(0.6, 1.0, mix(0.7, ckCrown, ckF2));
    k.clearcoat = p_ckCoat;
    k.clearcoatRough = clamp(p_ckCoatRough + p_ckMottle * 0.15 * (ckMot - 0.5), 0.0, 1.0);

}

void look_104(inout Look k) {
  p_upKind = texelFetch(lookSettings, ivec2(0, 104), 0).r;
  p_upColour = texelFetch(lookSettings, ivec2(1, 104), 0).rgb;
  p_upColour2 = texelFetch(lookSettings, ivec2(2, 104), 0).rgb;
  p_upThread = texelFetch(lookSettings, ivec2(3, 104), 0).r;
  p_upFleck = texelFetch(lookSettings, ivec2(4, 104), 0).r;
  p_upPrint = texelFetch(lookSettings, ivec2(5, 104), 0).r;
  p_upMotif = texelFetch(lookSettings, ivec2(6, 104), 0).r;
  p_upRelief = texelFetch(lookSettings, ivec2(7, 104), 0).r;
  p_upSheen = texelFetch(lookSettings, ivec2(8, 104), 0).r;
  p_upRough = texelFetch(lookSettings, ivec2(9, 104), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // a loop's or a thread's own detail (its ring, its crossing) is half of it across: faded out before it aliases
    float upF = kfade(p_upThread * 0.5);
    vec2 cl = upCloth(uv, p_upKind, p_upThread, seed);
    float h = mix(0.5, cl.x, upF);
    float lite = mix(0.5, cl.y, upF);
    // heather: fibres of the second colour twisted into the yarn, finer than a thread
    float fleck = smoothstep(0.55, 0.85, kn(uv / (p_upThread * 0.7) + seed * 3.0));
    float fleckMean = 0.18;
    float heather = p_upFleck * mix(fleckMean, fleck, kfade(p_upThread * 0.7));
    vec3 col = mix(p_upColour, p_upColour2, heather);
    // the dye's slow unevenness over the cloth
    col *= 0.94 + 0.1 * kfbm4(uv * 4.0 + seed);
    // the print: leaves in the second colour, then the weave over it
    float leaf = upLeaf(uv, p_upMotif, seed) * kfade(p_upMotif * 0.2);
    float leafMean = 0.12;
    col = mix(col, p_upColour2, p_upPrint * mix(leafMean, leaf, kfade(p_upMotif * 0.2)));
    // low places in shadow of the yarn round them, high places catch the light; a mesh's holes dark
    // (a loop pile, bouclé or terry, is soft: its loops shade one another only a little)
    bool upLoops = (p_upKind > 1.5 && p_upKind < 2.5) || (p_upKind > 3.5 && p_upKind < 4.5);
    float shade = p_upKind > 2.5 && p_upKind < 3.5 ? mix(0.25, 1.0, h) : upLoops ? 0.88 + 0.15 * h : 0.78 + 0.3 * h;
    col *= shade * (upLoops ? 0.95 + 0.07 * lite : 0.92 + 0.12 * lite);
    // a loop pile's yarn bunches: clumps of loops a few loops across, standing proud or sinking, seen from across a room
    float clump = upLoops ? kfbm4(uv / (p_upThread * 3.0) + seed) : 0.5;
    float clumpF = kfade(p_upThread * 1.5);
    clump = mix(0.5, clump, clumpF);
    col *= 0.86 + 0.28 * clump;
    h = mix(h, clump, upLoops ? 0.6 : 0.0);
    k.colour = col;
    k.rough = p_upRough;
    k.height = p_upRelief * h;
    k.ao = mix(0.75, 1.0, h);
    k.sheen = mix(p_upColour, vec3(1.0), 0.35) * p_upSheen;
    k.sheenRough = 0.7;

}

void look_105(inout Look k) {
  p_nfColour = texelFetch(lookSettings, ivec2(0, 105), 0).rgb;
  p_nfColour2 = texelFetch(lookSettings, ivec2(1, 105), 0).rgb;
  p_nfFibre = texelFetch(lookSettings, ivec2(2, 105), 0).r;
  p_nfFleck = texelFetch(lookSettings, ivec2(3, 105), 0).r;
  p_nfCloud = texelFetch(lookSettings, ivec2(4, 105), 0).r;
  p_nfPill = texelFetch(lookSettings, ivec2(5, 105), 0).r;
  p_nfRelief = texelFetch(lookSettings, ivec2(6, 105), 0).r;
  p_nfSheen = texelFetch(lookSettings, ivec2(7, 105), 0).r;
  p_nfRough = texelFetch(lookSettings, ivec2(8, 105), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the fuzz: two sizes of matted fibre, faded to their mean finer than a pixel
    float nfF = kfade(p_nfFibre * 2.0);
    float nfFuzz = mix(0.5, kfbm(uv / p_nfFibre + seed * 5.0), nfF);
    float nfOdd = smoothstep(0.62, 0.8, kn(uv / (p_nfFibre * 1.6) + seed * 11.0));
    nfOdd = mix(0.12, nfOdd, kfade(p_nfFibre * 1.6));
    vec3 nfCol = mix(p_nfColour, p_nfColour2, p_nfFleck * nfOdd);
    // the felt's density clouding over a hand's width, and its pills
    float nfCloudN = kfbm4(uv * 18.0 + seed);
    nfCol *= 1.0 + p_nfCloud * 0.4 * (nfCloudN - 0.5);
    float nfId, nfE;
    float nfD = kvor(uv / 0.004 + seed * 3.0, nfId, nfE);
    float nfPillM = (1.0 - smoothstep(0.08, 0.2, nfD)) * step(0.82, fract(nfId * 7.13)) * p_nfPill * kfade(0.002);
    nfCol *= 0.88 + 0.24 * nfFuzz + 0.15 * nfPillM;
    k.colour = nfCol;
    k.metal = 0.0;
    k.rough = p_nfRough;
    k.height = p_nfRelief * (nfFuzz + nfPillM * 1.5);
    k.ao = 0.85 + 0.15 * nfFuzz;
    k.sheen = mix(p_nfColour2, vec3(1.0), 0.3) * p_nfSheen;
    k.sheenRough = 0.85;

}

void look_106(inout Look k) {
  p_gfFace = texelFetch(lookSettings, ivec2(0, 106), 0).rgb;
  p_gfMark = texelFetch(lookSettings, ivec2(1, 106), 0).rgb;
  p_gfRed = texelFetch(lookSettings, ivec2(2, 106), 0).rgb;
  p_gfRadius = texelFetch(lookSettings, ivec2(3, 106), 0).r;
  p_gfTicks = texelFetch(lookSettings, ivec2(4, 106), 0).r;
  p_gfSweep = texelFetch(lookSettings, ivec2(5, 106), 0).r;
  p_gfRead = texelFetch(lookSettings, ivec2(6, 106), 0).r;
  p_gfNeedle = texelFetch(lookSettings, ivec2(7, 106), 0).rgb;
  p_gfGlow = texelFetch(lookSettings, ivec2(8, 106), 0).r;
  p_gfTachSteps = texelFetch(lookSettings, ivec2(9, 106), 0).r;
  p_gfTachRed = texelFetch(lookSettings, ivec2(10, 106), 0).r;
  p_gfNumerals = texelFetch(lookSettings, ivec2(11, 106), 0).r;
  p_gfSpeedTop = texelFetch(lookSettings, ivec2(12, 106), 0).r;
  p_gfSpeedStep = texelFetch(lookSettings, ivec2(13, 106), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 gfP;
    float gfRad, gfKind, gfReadAt;
    if (s2.x > 0.001) {
      gfRad = s2.x * 0.5;
      gfP = s3 / gfRad;
      gfKind = floor(s2.z + 0.5);
      gfReadAt = clamp(s2.w, 0.0, 1.0);
    } else {
      gfRad = p_gfRadius;
      gfP = uv / gfRad;
      gfKind = 0.0;
      gfReadAt = p_gfRead;
    }
    if (gfKind > 8.5 || gfKind < -0.5) gfKind = 0.0;
    if (gfKind > 2.5 && gfKind < 3.5) {
      // a warning lamp, unlit: its lens's colour by s2.w, deep and dark; the bulb behind it a faint brightening in its
      // middle; the frame's shadow round its square edge
      float gfWhich = floor(s2.w + 0.5);
      vec3 gfLens = gfWhich < 0.5 ? vec3(0.09, 0.006, 0.004) : gfWhich < 1.5 ? vec3(0.1, 0.045, 0.003) :
                    gfWhich < 2.5 ? vec3(0.008, 0.06, 0.012) : vec3(0.006, 0.02, 0.09);
      vec2 gfSq = abs(gfP);
      float gfEdge = max(gfSq.x, gfSq.y);
      float gfEw = fwidth(gfEdge) + 0.002;
      float gfBulb = 1.0 - smoothstep(0.0, 0.75, length(gfP));
      vec3 gfL = gfLens * (0.7 + 0.6 * gfBulb);
      gfL *= 1.0 - 0.6 * smoothstep(0.78 - gfEw, 0.95, gfEdge);
      k.colour = gfL;
      k.metal = 0.0;
      k.rough = 0.25;
      k.glow = vec3(0.0);
    } else {
    bool gfSmall = gfKind > 1.5;
    float gfR = length(gfP);
    float gfE = fwidth(gfR) * 0.75 + 0.002;
    // the angle from straight up, degrees, clockwise; the sweep is centred on straight up
    float gfA = degrees(atan(gfP.x, gfP.y));
    float gfSw = gfSmall ? 90.0 : p_gfSweep;
    float gfHalf = gfSw * 0.5;
    float gfFrom = gfA + gfHalf;
    float gfIn = step(-0.5, gfFrom) * step(gfFrom, gfSw + 0.5);
    float gfInk = 0.0;
    float gfRedInk = 0.0;
    float gfNumInk = 0.0;
    float gfNe = fwidth(gfP.x) + fwidth(gfP.y);
    bool gfNum = p_gfNumerals > 0.5;
    if (gfKind < 0.5) {
      float gfStep = gfSw / p_gfTicks;
      gfInk = gfIn * max(gfRing(gfFrom, gfStep, gfR, 0.8, 0.93, 0.012, gfE), gfRing(gfFrom, gfStep * 5.0, gfR, 0.68, 0.93, 0.024, gfE));
      if (gfNum) {
        float gfCount = floor(p_gfSpeedTop / p_gfSpeedStep + 0.5);
        for (int i = 0; i <= 40; i++) {
          if (float(i) > gfCount) break;
          float v = float(i) * p_gfSpeedStep;
          gfNumInk = max(gfNumInk, gfNumber(gfP, gfAt(gfSw * v / p_gfSpeedTop, gfSw, 0.52, vec2(0.0)), v, 0.11, gfNe));
        }
      }
    } else if (gfKind < 1.5) {
      // gfTachSteps steps of 500 rpm, long at each thousand; red from gfTachRed of the sweep, with a red arc inside
      // the marks
      float gfStep = gfSw / p_gfTachSteps;
      float gfMarks = gfIn * max(gfRing(gfFrom, gfStep, gfR, 0.8, 0.93, 0.014, gfE), gfRing(gfFrom, gfStep * 2.0, gfR, 0.68, 0.93, 0.026, gfE));
      float gfHot = step(gfSw * p_gfTachRed, gfFrom) * gfIn;
      float gfArc = gfHot * smoothstep(0.62 - gfE, 0.62, gfR) * (1.0 - smoothstep(0.68, 0.68 + gfE, gfR));
      gfInk = gfMarks * (1.0 - gfHot);
      gfRedInk = max(gfMarks * gfHot, gfArc);
      if (gfNum) {
        float gfTop = p_gfTachSteps * 0.5;
        for (int i = 0; i <= 12; i++) {
          if (float(i) > gfTop) break;
          gfNumInk = max(gfNumInk, gfNumber(gfP, gfAt(gfSw * float(i) / gfTop, gfSw, 0.48, vec2(0.0)), float(i), 0.15, gfNe));
        }
      }
    } else {
      // three long marks over the top arc, two short between; the low end's red
      float gfMarks = gfIn * max(gfRing(gfFrom, gfSw / 4.0, gfR, 0.72, 0.92, 0.03, gfE), gfRing(gfFrom, gfSw / 2.0, gfR, 0.56, 0.92, 0.05, gfE));
      float gfLow = step(gfFrom, gfSw * 0.12);
      gfInk = gfMarks * (1.0 - gfLow);
      gfRedInk = gfMarks * gfLow;
      if (gfNum && gfKind > 3.5) {
        // its three numerals inside the arc's ends and middle, about the needle's pivot low on the face
        vec3 gfVals = gfKind < 4.5 ? vec3(0.0, 1.0, 2.0) : gfKind < 5.5 ? vec3(0.0, 5.0, 10.0) :
                      gfKind < 6.5 ? vec3(40.0, 80.0, 120.0) : gfKind < 7.5 ? vec3(50.0, 100.0, 150.0) :
                      vec3(0.0, -1.0, 1.0);
        float gfSz = gfVals.z > 99.5 ? 0.17 : 0.2;
        for (int i = 0; i < 3; i++) {
          float v = gfVals[i];
          if (v < -0.5) continue;
          vec2 c = vec2(sin(radians(-48.0 + 48.0 * float(i))), cos(radians(-48.0 + 48.0 * float(i)))) * 0.52;
          c.y -= 0.14;
          gfNumInk = max(gfNumInk, gfNumber(gfP, c, v, gfSz, gfNe));
        }
      }
    }
    // the numerals finer than a pixel fade out
    gfNumInk *= kfade(0.1 * gfRad);
    gfInk = max(gfInk, gfNumInk);
    // the needle from just behind the hub out to the marks, tapering; a small gauge's pivots low, its needle long
    float gfAn = radians(-gfHalf + gfSw * gfReadAt);
    vec2 gfDir = vec2(sin(gfAn), cos(gfAn));
    vec2 gfQ = gfSmall ? gfP + vec2(0.0, 0.55) : gfP;
    float gfLen = gfSmall ? 1.3 : 0.8;
    float gfAlong = clamp(dot(gfQ, gfDir), -0.15, gfLen);
    float gfOff = length(gfQ - gfDir * gfAlong);
    float gfWide = 0.04 * (1.0 - 0.6 * max(gfAlong, 0.0) / gfLen);
    float gfNeedle = 1.0 - smoothstep(gfWide, gfWide + gfE, gfOff);
    gfNeedle *= step(length(gfP), 0.98);
    float gfHub = 1.0 - smoothstep(0.1, 0.1 + gfE, length(gfQ));
    gfHub *= step(length(gfP), 0.98);
    vec3 gfC = mix(p_gfFace, p_gfMark, clamp(gfInk, 0.0, 1.0));
    gfC = mix(gfC, p_gfRed, clamp(gfRedInk, 0.0, 1.0));
    gfC = mix(gfC, p_gfNeedle, gfNeedle);
    gfC = mix(gfC, vec3(0.02), gfHub);
    // finer than a pixel, the dial is the grey its marks make; and the bezel's shadow at its rim
    float gfF = kfade(0.1 * gfRad);
    gfC = mix(mix(p_gfFace, p_gfMark, 0.1), gfC, gfF);
    gfC *= 1.0 - 0.55 * smoothstep(0.9, 1.0, gfR);
    k.colour = gfC;
    k.metal = 0.0;
    k.rough = 0.5;
    k.glow = (p_gfMark * clamp(gfInk, 0.0, 1.0) + p_gfRed * clamp(gfRedInk, 0.0, 1.0) + p_gfNeedle * gfNeedle) * p_gfGlow * gfF * (1.0 - gfHub);
    }

}

void look_107(inout Look k) {
  p_clColour = texelFetch(lookSettings, ivec2(0, 107), 0).rgb;
  p_clRub = texelFetch(lookSettings, ivec2(1, 107), 0).rgb;
  p_clGrain = texelFetch(lookSettings, ivec2(2, 107), 0).r;
  p_clGrainDepth = texelFetch(lookSettings, ivec2(3, 107), 0).r;
  p_clCreases = texelFetch(lookSettings, ivec2(4, 107), 0).r;
  p_clCrease = texelFetch(lookSettings, ivec2(5, 107), 0).r;
  p_clWear = texelFetch(lookSettings, ivec2(6, 107), 0).r;
  p_clRough = texelFetch(lookSettings, ivec2(7, 107), 0).r;
  p_clRubRough = texelFetch(lookSettings, ivec2(8, 107), 0).r;
  p_clCoat = texelFetch(lookSettings, ivec2(9, 107), 0).r;
  p_clSheen = texelFetch(lookSettings, ivec2(10, 107), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the pebbled grain: cells pressed into the hide, high in their middles, furrowed at their edges
    float clId, clE;
    kvor(uv * p_clGrain + seed, clId, clE);
    float clSee = kfade(2.0 / p_clGrain);
    float clPeb = mix(0.7, smoothstep(0.0, 0.25, clE), clSee);
    float clCell = (kh1(clId) - 0.5) * clSee;
    // the dye's mottle over the hide
    float clMott = kfbm4(uv * 6.0 + seed);
    // soft creases: thin lines wandering every way over the hide where it bends (the contours of a slow noise), each
    // its own strength, some stretches with none
    float clN = kfbm(uv * p_clCreases * 0.3 + seed + 4.0);
    float clCr = (1.0 - smoothstep(0.0, 0.035, abs(clN - 0.5))) * smoothstep(0.4, 0.7, kfbm(uv * 3.0 + seed + 11.0));
    clCr *= p_clCrease * kfade(0.2 / p_clCreases);
    // the rubbing: the hide's own wear in patches, and the kind's hint where it is sat on or gripped
    float clRubA = clamp(p_clWear * smoothstep(0.5, 0.85, kfbm4(uv * 4.0 + seed + 2.0)) + s0.x, 0.0, 1.0);
    vec3 clC = p_clColour * (0.92 + 0.16 * clMott) * (1.0 + 0.035 * clCell);
    clC *= 0.94 + 0.06 * clPeb;
    clC = mix(clC, p_clRub, clRubA * 0.6);
    clC *= 1.0 - 0.18 * clCr;
    k.colour = clC;
    // rubbed smooth: the grain worn flatter and glossier where the hide is rubbed
    k.rough = clamp(mix(p_clRough, p_clRubRough, clRubA) + 0.08 * (1.0 - clPeb), 0.0, 1.0);
    k.height = p_clGrainDepth * clPeb * (1.0 - 0.6 * clRubA) - 0.0004 * clCr;
    k.ao = mix(0.85, 1.0, clPeb);
    k.clearcoat = p_clCoat;
    k.clearcoatRough = 0.35;
    k.sheen = mix(p_clColour, vec3(1.0), 0.5) * p_clSheen;
    k.sheenRough = 0.5;

}

void look_108(inout Look k) {
  p_pmColour = texelFetch(lookSettings, ivec2(0, 108), 0).rgb;
  p_pmPeel = texelFetch(lookSettings, ivec2(1, 108), 0).r;
  p_pmRelief = texelFetch(lookSettings, ivec2(2, 108), 0).r;
  p_pmRough = texelFetch(lookSettings, ivec2(3, 108), 0).r;
  p_pmCoat = texelFetch(lookSettings, ivec2(4, 108), 0).r;
  p_pmCoatRough = texelFetch(lookSettings, ivec2(5, 108), 0).r;
  p_pmOil = texelFetch(lookSettings, ivec2(6, 108), 0).r;
  p_pmOilColour = texelFetch(lookSettings, ivec2(7, 108), 0).rgb;
  p_pmOilStreaks = texelFetch(lookSettings, ivec2(8, 108), 0).r;
  p_pmOilRough = texelFetch(lookSettings, ivec2(9, 108), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float pmF = kfade(2.0 / p_pmPeel);
    float pmPeel = (1.0 - kcell(uv * p_pmPeel + seed)) * pmF;
    float pmFine = kn(uv * p_pmPeel * 2.7 + seed + 3.0) * kfade(1.0 / p_pmPeel);
    k.colour = p_pmColour * (0.985 + 0.03 * kfbm4(uv * 2.0 + seed));
    k.rough = clamp(p_pmRough + 0.04 * pmFine, 0.0, 1.0);
    k.height = p_pmRelief * (0.75 * pmPeel + 0.25 * pmFine);
    k.clearcoat = p_pmCoat;
    k.clearcoatRough = p_pmCoatRough;
    if (p_pmOil > 0.0) {
      // runs: noise drawn out along u, fine across v; blotches: a slow fbm; thick where both lie
      float pmRun = kn(vec2(uv.x * p_pmOilStreaks * 0.12, uv.y * p_pmOilStreaks) + seed + 5.0);
      float pmBlot = kfbm(uv * 2.5 + seed + 9.0);
      float pmThick = smoothstep(0.4, 0.8, 0.55 * pmRun + 0.45 * pmBlot);
      float pmO = clamp(p_pmOil * (0.15 + 0.85 * pmThick), 0.0, 1.0);
      vec3 pmOilC = p_pmOilColour * (0.7 + 0.6 * kn(vec2(uv.x * 3.0, uv.y * 40.0) + seed));
      k.colour = mix(k.colour, pmOilC, pmO);
      k.rough = mix(k.rough, p_pmOilRough + 0.5 * (1.0 - pmThick), pmO);
      k.clearcoat = mix(k.clearcoat, 0.0, pmO);
      k.height += p_pmOil * 0.00006 * pmThick;
    }

}

void look_109(inout Look k) {
  p_bmColour = texelFetch(lookSettings, ivec2(0, 109), 0).rgb;
  p_bmLines = texelFetch(lookSettings, ivec2(1, 109), 0).r;
  p_bmStreak = texelFetch(lookSettings, ivec2(2, 109), 0).r;
  p_bmLong = texelFetch(lookSettings, ivec2(3, 109), 0).r;
  p_bmRough = texelFetch(lookSettings, ivec2(4, 109), 0).r;
  p_bmMetal = texelFetch(lookSettings, ivec2(5, 109), 0).r;
  p_bmRelief = texelFetch(lookSettings, ivec2(6, 109), 0).r;
  p_bmMirror = texelFetch(lookSettings, ivec2(7, 109), 0).r;
  p_bmSky = texelFetch(lookSettings, ivec2(8, 109), 0).rgb;
  p_bmWall = texelFetch(lookSettings, ivec2(9, 109), 0).rgb;
  p_bmFloor = texelFetch(lookSettings, ivec2(10, 109), 0).rgb;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 bmG = dot(s3, s3) > 0.25 ? normalize(s3) : vec2(1.0, 0.0);
    // along the brushing, across it
    vec2 bmQ = vec2(dot(uv, bmG), dot(uv, vec2(-bmG.y, bmG.x)));
    // the scratches: noise stretched far along the brushing, one row a scratch, faded to its mean where a scratch is
    // under a pixel; a few deeper, longer ones over them
    float bmFine = mix(0.5, kn(vec2(bmQ.x * p_bmLong * 4.0, bmQ.y * p_bmLines) + seed), kfade(2.0 / p_bmLines));
    float bmDeep = mix(0.5, kn(vec2(bmQ.x * p_bmLong, bmQ.y * p_bmLines * 0.18) + seed + 17.0), kfade(8.0 / p_bmLines));
    float bmS = 0.75 * bmFine + 0.25 * smoothstep(0.35, 0.8, bmDeep);
    // a slow cloud of the belt's passes, so a big sheet isn't one flat grey
    float bmPass = kfbm4(vec2(bmQ.x * 0.6, bmQ.y * 7.0) + seed * 1.3);
    vec3 bmC = p_bmColour * (1.0 + p_bmStreak * (bmS - 0.5) * 0.9) * (0.94 + 0.12 * bmPass);
    k.colour = bmC;
    k.metal = p_bmMetal;
    k.rough = clamp(p_bmRough + 0.12 * (bmS - 0.5) + 0.05 * (bmPass - 0.5), 0.03, 1.0);
    k.height = p_bmRelief * (bmS - 0.5);
    // the room mirrored, smeared along the brushing: its ray tipped across the scratches by each one's slope
    vec3 bmV = normalize(wp - cameraPosition);
    vec3 bmN = normalize(wn);
    vec3 bmR = reflect(bmV, bmN);
    float bmCos = clamp(dot(-bmV, bmN), 0.0, 1.0);
    float bmFres = 0.7 + 0.3 * pow(1.0 - bmCos, 3.0);
    vec3 bmRoom = rmRoom(normalize(bmR + 0.08 * (bmS - 0.5) * vec3(1.0, 0.0, 1.0)), clamp(p_bmRough * 2.2, 0.0, 1.0), p_bmSky, p_bmWall, p_bmFloor);
    k.glow = p_bmMirror * bmRoom * bmC * bmFres * (0.85 + 0.3 * bmS);
    if (lookView > 0.5 && lookView < 1.5) k.colour = vec3(0.5 + 0.5 * bmG.x, 0.5 + 0.5 * bmG.y, 0.5);

}

void look_110(inout Look k) {
  p_pcTint = texelFetch(lookSettings, ivec2(0, 110), 0).rgb;
  p_pcSky = texelFetch(lookSettings, ivec2(1, 110), 0).rgb;
  p_pcHorizon = texelFetch(lookSettings, ivec2(2, 110), 0).rgb;
  p_pcFloor = texelFetch(lookSettings, ivec2(3, 110), 0).rgb;
  p_pcBlur = texelFetch(lookSettings, ivec2(4, 110), 0).r;
  p_pcWindow = texelFetch(lookSettings, ivec2(5, 110), 0).r;
  p_pcRough = texelFetch(lookSettings, ivec2(6, 110), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec3 pcN = normalize(wn);
    vec3 pcI = normalize(wp - cameraPosition);
    vec3 pcR = reflect(pcI, pcN);
    // how far up the reflected line points: -1 straight down, 1 straight up
    float pcUp = pcR.y;
    float pcB = p_pcBlur;
    // the floor below, the sky above, a bright band at the horizon between them
    vec3 pcEnv = mix(p_pcFloor, p_pcSky, smoothstep(-pcB, pcB, pcUp));
