  p_nfFibre = texelFetch(lookSettings, ivec2(2, 296), 0).r;
  p_nfFleck = texelFetch(lookSettings, ivec2(3, 296), 0).r;
  p_nfCloud = texelFetch(lookSettings, ivec2(4, 296), 0).r;
  p_nfPill = texelFetch(lookSettings, ivec2(5, 296), 0).r;
  p_nfRelief = texelFetch(lookSettings, ivec2(6, 296), 0).r;
  p_nfSheen = texelFetch(lookSettings, ivec2(7, 296), 0).r;
  p_nfRough = texelFetch(lookSettings, ivec2(8, 296), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the fuzz: two sizes of matted fibre, faded to their mean finer than a pixel
    float nfF = kfade(p_nfFibre * 2.0);
    float nfFuzz = mix(0.5, kfbm(uv / p_nfFibre + seed * 5.0), nfF);
    float nfOdd = smoothstep(0.62, 0.8, kn(uv / (p_nfFibre * 1.6) + seed * 11.0));
