void look_319(inout Look k) {
  p_gvColour = texelFetch(lookSettings, ivec2(0, 319), 0).rgb;
  p_gvSpangle = texelFetch(lookSettings, ivec2(1, 319), 0).r;
  p_gvTone = texelFetch(lookSettings, ivec2(2, 319), 0).r;
  p_gvRough = texelFetch(lookSettings, ivec2(3, 319), 0).r;
  p_gvRoughVar = texelFetch(lookSettings, ivec2(4, 319), 0).r;
  p_gvBloom = texelFetch(lookSettings, ivec2(5, 319), 0).r;
  p_gvMetal = texelFetch(lookSettings, ivec2(6, 319), 0).r;
  p_gvRelief = texelFetch(lookSettings, ivec2(7, 319), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float gvId, gvE;
    vec2 gvP = uv * p_gvSpangle + seed * 11.0;
    gvP += vec2(kn(uv * 9.0 + seed), kn(uv * 9.0 + seed + 4.0)) * 0.6;
    kvor(gvP, gvId, gvE);
    float gvF = kfade(1.5 / p_gvSpangle);
    // the dendrites: fine lines along the crystal's own angle
    float gvA = gvId * 6.2832;
    vec2 gvDir = vec2(cos(gvA), sin(gvA));
    float gvDen = abs(sin(dot(uv, gvDir) * p_gvSpangle * 40.0 + kn(uv * p_gvSpangle * 6.0) * 3.0));
    gvDen = smoothstep(0.6, 1.0, gvDen) * kfade(0.8 / (p_gvSpangle * 12.0)) * gvF;
    float gvB = smoothstep(0.45, 0.8, kfbm4(uv * 2.5 + seed + 2.0)) * p_gvBloom;
    float gvT = (gvId - 0.5) * 2.0 * p_gvTone * gvF;
    vec3 c = p_gvColour * (1.0 + gvT) * (1.0 - 0.06 * gvDen);
    c = mix(c, vec3(0.56, 0.56, 0.55), gvB);
    k.colour = c;
    k.metal = mix(p_gvMetal, 0.3, gvB);
    k.rough = clamp(p_gvRough + p_gvRoughVar * (kh1(gvId * 17.0) - 0.5) * 2.0 * gvF + 0.08 * gvDen + 0.3 * gvB, 0.05, 1.0);
    k.height = p_gvRelief * (smoothstep(0.03, 0.0, gvE) * gvF + 0.5 * gvDen);

}

void look_320(inout Look k) {
  p_pcTint = texelFetch(lookSettings, ivec2(0, 320), 0).rgb;
  p_pcSky = texelFetch(lookSettings, ivec2(1, 320), 0).rgb;
  p_pcHorizon = texelFetch(lookSettings, ivec2(2, 320), 0).rgb;
  p_pcFloor = texelFetch(lookSettings, ivec2(3, 320), 0).rgb;
  p_pcBlur = texelFetch(lookSettings, ivec2(4, 320), 0).r;
  p_pcWindow = texelFetch(lookSettings, ivec2(5, 320), 0).r;
  p_pcRough = texelFetch(lookSettings, ivec2(6, 320), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec3 pcN = normalize(wn);
    vec3 pcI = normalize(wp - cameraPosition);
    vec3 pcR = reflect(pcI, pcN);
    // how far up the reflected line points: -1 straight down, 1 straight up
    float pcUp = pcR.y;
    float pcB = p_pcBlur;
    // the floor below, the sky above, a bright band at the horizon between them
    vec3 pcEnv = mix(p_pcFloor, p_pcSky, smoothstep(-pcB, pcB, pcUp));
    pcEnv = mix(pcEnv, p_pcHorizon, exp(-pcUp * pcUp / max(0.002, pcB * pcB * 0.25)) * 0.55);
    // a soft window of light high up and toward one side, so a round part has its one bright spot
    float pcW = smoothstep(0.82, 0.97, dot(pcR, normalize(vec3(0.35, 0.85, 0.4))));
    pcEnv += vec3(p_pcWindow) * pcW;
    // the faint swirls of polishing, gone to their mean where a pixel is as wide
    float pcSw = mix(0.5, kn(uv * 900.0 + seed), kfade(0.002));
    k.colour = clamp(pcEnv * p_pcTint * (0.98 + 0.04 * pcSw), 0.0, 1.0);
    k.metal = 0.0;
    k.rough = p_pcRough;

}

