  p_cmBloom = texelFetch(lookSettings, ivec2(6, 330), 0).r;
  p_cmBloomColour = texelFetch(lookSettings, ivec2(7, 330), 0).rgb;
  p_cmHeat = texelFetch(lookSettings, ivec2(8, 330), 0).r;
  p_cmHeatColour = texelFetch(lookSettings, ivec2(9, 330), 0).rgb;
  p_cmGrime = texelFetch(lookSettings, ivec2(10, 330), 0).r;
  p_cmGrimeColour = texelFetch(lookSettings, ivec2(11, 330), 0).rgb;
  p_cmMirror = texelFetch(lookSettings, ivec2(12, 330), 0).r;
  p_cmSky = texelFetch(lookSettings, ivec2(13, 330), 0).rgb;
  p_cmWall = texelFetch(lookSettings, ivec2(14, 330), 0).rgb;
  p_cmFloor = texelFetch(lookSettings, ivec2(15, 330), 0).rgb;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the sand's grain: fine bumps, and here and there a pit, each fading to its mean where finer than a pixel
    float cmF = kfade(2.0 / p_cmSand);
    float cmG = mix(0.5, kn(uv * p_cmSand + seed), cmF);
    float cmG2 = mix(0.5, kn(uv * p_cmSand * 0.43 + seed + 5.0), kfade(4.0 / p_cmSand));
