  p_plRelief = texelFetch(lookSettings, ivec2(2, 367), 0).r;
  p_plRough = texelFetch(lookSettings, ivec2(3, 367), 0).r;
  p_plRoughVar = texelFetch(lookSettings, ivec2(4, 367), 0).r;
