    float lpUp = mix(1.0 - 4.0 * lpF.y * lpF.y, 1.0, p_lpFlute);
    float lpBump = lpAcross * lpUp;
    // the thin line where two prisms meet (a flute's only between flutes)
    float lpRim = max(abs(lpF.x), abs(lpF.y) * (1.0 - p_lpFlute));
    float lpEdge = smoothstep(0.43, 0.5, lpRim) * lpSee;
    float lpTone = mix(1.0, 1.0 + p_lpTwinkle * (kh(lpId + seed) - 0.5), lpSee);
    // the reflector behind, through each prism's middle, brightest looked at straight on
    float lpFace = clamp(dot(normalize(cameraPosition - wp), normalize(wn)), 0.0, 1.0);
    float lpRef = p_lpReflector * lpFace * lpFace * mix(0.55, 0.25 + 0.9 * lpBump, lpSee) * lpTone;
    k.colour = p_lpColour * mix(1.0, 0.8 + 0.35 * lpBump, lpSee) * lpTone * (1.0 - 0.45 * lpEdge) + p_lpBack * lpRef;
    k.metal = 0.0;
    k.rough = 0.04 + 0.12 * lpEdge;
    k.height = p_lpDepth * lpBump * lpSee;
    k.clearcoat = 1.0;
    k.clearcoatRough = 0.03;
    // lit: the lamp's light out of the glass, round the bulb and through each prism's middle
    float lpHot = exp(-dot(uv, uv) / (p_lpSpotSize * p_lpSpotSize));
    float lpLit = (1.0 - p_lpSpot) + p_lpSpot * 2.0 * lpHot;
    k.glow = p_lpGlow * lpLit * mix(1.0, 0.65 + 0.55 * lpBump, lpSee) * lpTone * (1.0 - 0.5 * lpEdge);

}

void look_34(inout Look k) {
  p_rrColour = texelFetch(lookSettings, ivec2(0, 34), 0).rgb;
  p_rrReturn = texelFetch(lookSettings, ivec2(1, 34), 0).rgb;
  p_rrTight = texelFetch(lookSettings, ivec2(2, 34), 0).r;
  p_rrCell = texelFetch(lookSettings, ivec2(3, 34), 0).r;
  p_rrSeal = texelFetch(lookSettings, ivec2(4, 34), 0).r;
  p_rrRelief = texelFetch(lookSettings, ivec2(5, 34), 0).r;
  p_rrPrism = texelFetch(lookSettings, ivec2(6, 34), 0).r;
  p_rrGlitter = texelFetch(lookSettings, ivec2(7, 34), 0).r;
  p_rrRough = texelFetch(lookSettings, ivec2(8, 34), 0).r;
  p_rrCoat = texelFetch(lookSettings, ivec2(9, 34), 0).r;
  p_rrCoatRough = texelFetch(lookSettings, ivec2(10, 34), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the seal net: a regular net of diamond cells (the sheeting's grid turned 45 degrees), their edges the darker
    // seal lines
    vec2 rrD = vec2(uv.x + uv.y, uv.x - uv.y) * 0.7071 / p_rrCell;
    vec2 rrCellId = floor(rrD);
    vec2 rrF = abs(fract(rrD) - 0.5);
    float rrEdge = 0.5 - max(rrF.x, rrF.y);
    float rrNetF = kfade(p_rrCell * 0.15);
    float rrLine = (1.0 - smoothstep(0.02, 0.06, rrEdge)) * rrNetF;
    // the prisms: a fine glitter, each prism a cell of its own brightness, faded to its mean far off
    float rrPF = kfade(2.0 / p_rrPrism);
    float rrP = mix(0.5, kh(floor(uv * p_rrPrism) + seed), rrPF);
    // each seal cell its own slight tone, as the sheeting's cells catch the light a little differently
    float rrTone = 0.96 + 0.08 * kh(rrCellId + seed);
    vec3 rrFace = p_rrColour * rrTone * (1.0 - p_rrSeal * rrLine);
    k.colour = rrFace * (1.0 + p_rrGlitter * (rrP - 0.5));
    // the light sent back to the eye: strongest square on, none along the face, none from a seal line
    float rrFacing = clamp(dot(normalize(cameraPosition - wp), normalize(wn)), 0.0, 1.0);
    float rrBack = pow(rrFacing, p_rrTight);
    k.glow = p_rrReturn * rrBack * rrTone * (1.0 - p_rrSeal * rrLine) * (1.0 + p_rrGlitter * (rrP - 0.5));
    k.rough = clamp(p_rrRough + 0.3 * rrLine, 0.0, 1.0);
    k.clearcoat = p_rrCoat;
    k.clearcoatRough = p_rrCoatRough;
    k.height = p_rrRelief * (1.0 - rrLine) * rrNetF;

}

void look_35(inout Look k) {
  p_glTint = texelFetch(lookSettings, ivec2(0, 35), 0).rgb;
  p_glTint2 = texelFetch(lookSettings, ivec2(1, 35), 0).rgb;
  p_glWaves = texelFetch(lookSettings, ivec2(2, 35), 0).r;
  p_glWaveDepth = texelFetch(lookSettings, ivec2(3, 35), 0).r;
  p_glSeeds = texelFetch(lookSettings, ivec2(4, 35), 0).r;
  p_glRough = texelFetch(lookSettings, ivec2(5, 35), 0).r;
  p_glAlpha = texelFetch(lookSettings, ivec2(6, 35), 0).r;
  p_glAlphaVar = texelFetch(lookSettings, ivec2(7, 35), 0).r;
  p_glRibs = texelFetch(lookSettings, ivec2(8, 35), 0).r;
  p_glRibWide = texelFetch(lookSettings, ivec2(9, 35), 0).r;
  p_glRibAlpha = texelFetch(lookSettings, ivec2(10, 35), 0).r;
  p_glGlow = texelFetch(lookSettings, ivec2(11, 35), 0).rgb;
  p_glCrease = texelFetch(lookSettings, ivec2(12, 35), 0).r;
  p_glCreaseFreq = texelFetch(lookSettings, ivec2(13, 35), 0).r;
  p_glBands = texelFetch(lookSettings, ivec2(14, 35), 0).r;
  p_glBandHigh = texelFetch(lookSettings, ivec2(15, 35), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float wave = kfbm4(uv * p_glWaves + seed);
    float seeds = smoothstep(0.08, 0.02, kcell(uv * 60.0 + seed)) * kfade(0.01);
    // the twin wall's ribs, along u, one every 1 / glRibs metres across v; under a pixel, their mean cover
    float glRib = 0.0;
    if (p_glRibs > 0.0) {
      float glRd = abs(fract(uv.y * p_glRibs) - 0.5) * 2.0;
      float glRw = fwidth(uv.y * p_glRibs) * 2.0;
      float glLine = 1.0 - smoothstep(p_glRibWide - glRw, p_glRibWide + glRw, 1.0 - glRd);
      glRib = mix(p_glRibWide, glLine, kfade(1.5 / p_glRibs));
    }
    // the film's creases and wound bands, level round the load (the world's height, and the way along the face)
    float glFold = 0.0, glBand = 0.0;
    if (p_glCrease > 0.0 || p_glBands > 0.0) {
      vec3 glSide = cross(vec3(0.0, 1.0, 0.0), wn);
      float glAlong = dot(glSide, glSide) > 0.01 ? dot(wp, normalize(glSide)) : wp.x;
      float glUp = wp.y + 0.03 * kn(vec2(glAlong * 2.0, 0.0) + seed);
      float glF = kn(vec2(glAlong * 1.6, glUp * p_glCreaseFreq) + seed * 1.7);
      float glF2 = kn(vec2(glAlong * 3.1, glUp * p_glCreaseFreq * 2.3) + seed + 5.0);
      glFold = p_glCrease * mix(0.35, pow(1.0 - abs(glF * 2.0 - 1.0), 6.0) * 0.75 + pow(1.0 - abs(glF2 * 2.0 - 1.0), 8.0) * 0.4,
                                kfade(1.0 / p_glCreaseFreq));
      float glB = fract(glUp / p_glBandHigh + 0.15 * kn(vec2(glAlong * 0.8, 3.0) + seed));
      glBand = p_glBands * smoothstep(0.55, 0.62, glB) * (0.8 + 0.4 * kn(vec2(glAlong * 4.0, glUp * 6.0) + seed));
    }
    k.colour = mix(p_glTint, p_glTint2, wave) + seeds * p_glSeeds + vec3(0.12 * glRib + 0.25 * glFold + 0.06 * glBand);
    k.rough = p_glRough + p_glRough * wave;
    k.metal = 0.0;
    k.height = p_glWaveDepth * (wave - 0.5) + 0.0003 * glFold;
    k.alpha = clamp(p_glAlpha + p_glAlphaVar * wave + p_glRibAlpha * glRib + 0.35 * glFold + 0.18 * glBand, 0.0, 1.0);
    k.glow = p_glGlow * (0.9 + 0.2 * wave) * (1.0 + 0.4 * glRib);

}

void look_36(inout Look k) {
  p_pcTint = texelFetch(lookSettings, ivec2(0, 36), 0).rgb;
  p_pcSky = texelFetch(lookSettings, ivec2(1, 36), 0).rgb;
  p_pcHorizon = texelFetch(lookSettings, ivec2(2, 36), 0).rgb;
  p_pcFloor = texelFetch(lookSettings, ivec2(3, 36), 0).rgb;
  p_pcBlur = texelFetch(lookSettings, ivec2(4, 36), 0).r;
  p_pcWindow = texelFetch(lookSettings, ivec2(5, 36), 0).r;
  p_pcRough = texelFetch(lookSettings, ivec2(6, 36), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec3 pcN = normalize(wn);
    vec3 pcI = normalize(wp - cameraPosition);
    vec3 pcR = reflect(pcI, pcN);
    // how far up the reflected line points: -1 straight down, 1 straight up
    float pcUp = pcR.y;
    float pcB = p_pcBlur;
    // the floor below, the sky above, a bright band at the horizon between them
    vec3 pcEnv = mix(p_pcFloor, p_pcSky, smoothstep(-pcB, pcB, pcUp));
    pcEnv = mix(pcEnv, p_pcHorizon, exp(-pcUp * pcUp / max(0.002, pcB * pcB * 0.25)) * 0.55);
    // a soft window of light high up and toward one side, so a round part has its one bright spot
    float pcW = smoothstep(0.82, 0.97, dot(pcR, normalize(vec3(0.35, 0.85, 0.4))));
    pcEnv += vec3(p_pcWindow) * pcW;
    // the faint swirls of polishing, gone to their mean where a pixel is as wide
    float pcSw = mix(0.5, kn(uv * 900.0 + seed), kfade(0.002));
    k.colour = clamp(pcEnv * p_pcTint * (0.98 + 0.04 * pcSw), 0.0, 1.0);
    k.metal = 0.0;
    k.rough = p_pcRough;

}

