    float seeds = smoothstep(0.08, 0.02, kcell(uv * 60.0 + seed)) * kfade(0.01);
    // the twin wall's ribs, along u, one every 1 / glRibs metres across v; under a pixel, their mean cover
    float glRib = 0.0;
    if (p_glRibs > 0.0) {
      float glRd = abs(fract(uv.y * p_glRibs) - 0.5) * 2.0;
      float glRw = fwidth(uv.y * p_glRibs) * 2.0;
      float glLine = 1.0 - smoothstep(p_glRibWide - glRw, p_glRibWide + glRw, 1.0 - glRd);
      glRib = mix(p_glRibWide, glLine, kfade(1.5 / p_glRibs));
    }
    // the film's creases and wound bands, level round the load (the world's height, and the way along the face)
    float glFold = 0.0, glBand = 0.0;
    if (p_glCrease > 0.0 || p_glBands > 0.0) {
      vec3 glSide = cross(vec3(0.0, 1.0, 0.0), wn);
      float glAlong = dot(glSide, glSide) > 0.01 ? dot(wp, normalize(glSide)) : wp.x;
      float glUp = wp.y + 0.03 * kn(vec2(glAlong * 2.0, 0.0) + seed);
      float glF = kn(vec2(glAlong * 1.6, glUp * p_glCreaseFreq) + seed * 1.7);
      float glF2 = kn(vec2(glAlong * 3.1, glUp * p_glCreaseFreq * 2.3) + seed + 5.0);
      glFold = p_glCrease * mix(0.35, pow(1.0 - abs(glF * 2.0 - 1.0), 6.0) * 0.75 + pow(1.0 - abs(glF2 * 2.0 - 1.0), 8.0) * 0.4,
                                kfade(1.0 / p_glCreaseFreq));
      float glB = fract(glUp / p_glBandHigh + 0.15 * kn(vec2(glAlong * 0.8, 3.0) + seed));
      glBand = p_glBands * smoothstep(0.55, 0.62, glB) * (0.8 + 0.4 * kn(vec2(glAlong * 4.0, glUp * 6.0) + seed));
    }
    k.colour = mix(p_glTint, p_glTint2, wave) + seeds * p_glSeeds + vec3(0.12 * glRib + 0.25 * glFold + 0.06 * glBand);
    k.rough = p_glRough + p_glRough * wave;
    k.metal = 0.0;
    k.height = p_glWaveDepth * (wave - 0.5) + 0.0003 * glFold;
    k.alpha = clamp(p_glAlpha + p_glAlphaVar * wave + p_glRibAlpha * glRib + 0.35 * glFold + 0.18 * glBand, 0.0, 1.0);
    k.glow = p_glGlow * (0.9 + 0.2 * wave) * (1.0 + 0.4 * glRib);

}

void look_65(inout Look k) {
  p_omColour = texelFetch(lookSettings, ivec2(0, 65), 0).rgb;
  p_omPitchV = texelFetch(lookSettings, ivec2(1, 65), 0).r;
  p_omBarV = texelFetch(lookSettings, ivec2(2, 65), 0).r;
  p_omDeepU = texelFetch(lookSettings, ivec2(3, 65), 0).r;
  p_omPitchU = texelFetch(lookSettings, ivec2(4, 65), 0).r;
  p_omBarU = texelFetch(lookSettings, ivec2(5, 65), 0).r;
  p_omDeepV = texelFetch(lookSettings, ivec2(6, 65), 0).r;
  p_omRound = texelFetch(lookSettings, ivec2(7, 65), 0).r;
  p_omTwist = texelFetch(lookSettings, ivec2(8, 65), 0).r;
  p_omSpangle = texelFetch(lookSettings, ivec2(9, 65), 0).r;
  p_omRough = texelFetch(lookSettings, ivec2(10, 65), 0).r;
  p_omMetal = texelFetch(lookSettings, ivec2(11, 65), 0).r;
  p_omSide = texelFetch(lookSettings, ivec2(12, 65), 0).r;
  p_omGrime = texelFetch(lookSettings, ivec2(13, 65), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the panel's ways in the world (u's and v's), from the uv's change across the pixel, so the eye's slant across
    // each set of bars is known
    vec3 omDpx = dFdx(wp), omDpy = dFdy(wp);
    vec2 omDux = dFdx(uv), omDuy = dFdy(uv);
    float omDet = omDux.x * omDuy.y - omDux.y * omDuy.x;
    vec3 omTu = abs(omDet) > 1e-14 ? (omDpx * omDuy.y - omDpy * omDux.y) / omDet : vec3(1.0, 0.0, 0.0);
    vec3 omTv = abs(omDet) > 1e-14 ? (omDpy * omDux.x - omDpx * omDuy.x) / omDet : vec3(0.0, 0.0, 1.0);
    omTu = dot(omTu, omTu) > 1e-12 ? normalize(omTu) : vec3(1.0, 0.0, 0.0);
    omTv = dot(omTv, omTv) > 1e-12 ? normalize(omTv) : vec3(0.0, 0.0, 1.0);
    vec3 omN = normalize(wn);
    vec3 omV = normalize(cameraPosition - wp);
    float omVn = max(abs(dot(omV, omN)), 0.08);
    // the eye's slant across each set: how far, per metre of a bar's depth, it sees down the bar's side, and to which
    // side of the bar (away from the eye)
    float omVv = dot(omV, omTv), omVu = dot(omV, omTu);
    float omSideLenV = min(p_omDeepU * abs(omVv) / omVn, p_omPitchV - p_omBarV);
    float omSideLenU = min(p_omDeepV * abs(omVu) / omVn, p_omPitchU - p_omBarU);
    float omShiftV = -sign(omVv) * omSideLenV * 0.5;
    float omShiftU = -sign(omVu) * omSideLenU * 0.5;
    vec2 omF = vec2(length(vec2(omDux.x, omDuy.x)), length(vec2(omDux.y, omDuy.y))) * 1.2;
    // each set's cover: its tops and the sides the eye sees, and its tops alone
    float omA = omCover(uv.y - omShiftV, p_omPitchV, p_omBarV + omSideLenV, omF.y);
    float omB = omCover(uv.x - omShiftU, p_omPitchU, p_omBarU + omSideLenU, omF.x);
    float omTopA = omCover(uv.y, p_omPitchV, p_omBarV, omF.y);
    float omTopB = omCover(uv.x, p_omPitchU, p_omBarU, omF.x);
    float omCov = 1.0 - (1.0 - omA) * (1.0 - omB);
    // the share of what is seen that is a bar's side, not its top (the first set lies over the second where they cross)
    float omSideA = max(omA - omTopA, 0.0);
    float omSideB = max(omB - omTopB, 0.0) * (1.0 - omTopA);
    float omSide = clamp((omSideA + omSideB) / max(omCov, 1e-4), 0.0, 1.0);
    // across a bar, -1 to 1 (for the round wires' shading), and along the cross bars' twist
    float omPv = uv.y - floor(uv.y / p_omPitchV + 0.5) * p_omPitchV;
    float omPu = uv.x - floor(uv.x / p_omPitchU + 0.5) * p_omPitchU;
    float omXv = clamp(omPv / (p_omBarV * 0.5), -1.0, 1.0);
    float omXu = clamp(omPu / (p_omBarU * 0.5), -1.0, 1.0);
    float omFadeV = kfade(p_omBarV), omFadeU = kfade(p_omBarU);
    float omOnA = omTopA / max(omCov, 1e-4);
    float omOnB = omTopB * (1.0 - omTopA) / max(omCov, 1e-4);
    float omRoundA = 1.0 - p_omRound * 0.5 * omXv * omXv * omFadeV;
    float omRoundB = 1.0 - p_omRound * 0.5 * omXu * omXu * omFadeU;
    float omTw = 1.0;
    if (p_omTwist > 0.0) {
      float omFacet = step(0.5, fract(uv.y * p_omTwist + omXu * 0.5));
      omTw = mix(0.94, 0.78 + 0.32 * omFacet, kfade(1.0 / p_omTwist));
    }
    float omShade = mix(1.0, omRoundA, omOnA) * mix(1.0, omRoundB * omTw, omOnB) * (1.0 - p_omSide * omSide);
    // the finish: the zinc's spangle or the coat's even colour, grime in a slow cloud
    float omId, omE;
    kvor(uv * 30.0 + seed * 11.0, omId, omE);
    float omSp = 1.0 + p_omSpangle * 0.12 * (omId - 0.5) * 2.0 * kfade(0.03);
    float omG = p_omGrime * smoothstep(0.35, 0.8, kfbm4(uv * 2.5 + seed + 3.0));
    k.colour = p_omColour * omSp * (1.0 - 0.35 * omG) * omShade;
    k.metal = mix(p_omMetal, p_omMetal * 0.5, omG);
    k.rough = clamp(p_omRough + p_omSpangle * 0.1 * (kh1(omId * 17.0) - 0.5) + 0.25 * omG, 0.05, 1.0);
    k.alpha = omCov;
    k.ao = 1.0 - 0.4 * omSide;

}

void look_66(inout Look k) {
  p_pmColour = texelFetch(lookSettings, ivec2(0, 66), 0).rgb;
  p_pmPeel = texelFetch(lookSettings, ivec2(1, 66), 0).r;
  p_pmRelief = texelFetch(lookSettings, ivec2(2, 66), 0).r;
  p_pmRough = texelFetch(lookSettings, ivec2(3, 66), 0).r;
  p_pmCoat = texelFetch(lookSettings, ivec2(4, 66), 0).r;
  p_pmCoatRough = texelFetch(lookSettings, ivec2(5, 66), 0).r;
  p_pmOil = texelFetch(lookSettings, ivec2(6, 66), 0).r;
  p_pmOilColour = texelFetch(lookSettings, ivec2(7, 66), 0).rgb;
  p_pmOilStreaks = texelFetch(lookSettings, ivec2(8, 66), 0).r;
  p_pmOilRough = texelFetch(lookSettings, ivec2(9, 66), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float pmF = kfade(2.0 / p_pmPeel);
    float pmPeel = (1.0 - kcell(uv * p_pmPeel + seed)) * pmF;
    float pmFine = kn(uv * p_pmPeel * 2.7 + seed + 3.0) * kfade(1.0 / p_pmPeel);
    k.colour = p_pmColour * (0.985 + 0.03 * kfbm4(uv * 2.0 + seed));
    k.rough = clamp(p_pmRough + 0.04 * pmFine, 0.0, 1.0);
    k.height = p_pmRelief * (0.75 * pmPeel + 0.25 * pmFine);
    k.clearcoat = p_pmCoat;
    k.clearcoatRough = p_pmCoatRough;
    if (p_pmOil > 0.0) {
      // runs: noise drawn out along u, fine across v; blotches: a slow fbm; thick where both lie
      float pmRun = kn(vec2(uv.x * p_pmOilStreaks * 0.12, uv.y * p_pmOilStreaks) + seed + 5.0);
      float pmBlot = kfbm(uv * 2.5 + seed + 9.0);
      float pmThick = smoothstep(0.4, 0.8, 0.55 * pmRun + 0.45 * pmBlot);
      float pmO = clamp(p_pmOil * (0.15 + 0.85 * pmThick), 0.0, 1.0);
      vec3 pmOilC = p_pmOilColour * (0.7 + 0.6 * kn(vec2(uv.x * 3.0, uv.y * 40.0) + seed));
      k.colour = mix(k.colour, pmOilC, pmO);
      k.rough = mix(k.rough, p_pmOilRough + 0.5 * (1.0 - pmThick), pmO);
      k.clearcoat = mix(k.clearcoat, 0.0, pmO);
      k.height += p_pmOil * 0.00006 * pmThick;
    }

}

void look_67(inout Look k) {
  p_tpColour = texelFetch(lookSettings, ivec2(0, 67), 0).rgb;
  p_tpFaded = texelFetch(lookSettings, ivec2(1, 67), 0).rgb;
  p_tpFade = texelFetch(lookSettings, ivec2(2, 67), 0).r;
  p_tpGrain = texelFetch(lookSettings, ivec2(3, 67), 0).r;
  p_tpGrainDepth = texelFetch(lookSettings, ivec2(4, 67), 0).r;
  p_tpRough = texelFetch(lookSettings, ivec2(5, 67), 0).r;
  p_tpDust = texelFetch(lookSettings, ivec2(6, 67), 0).r;
  p_tpDustColour = texelFetch(lookSettings, ivec2(7, 67), 0).rgb;
  p_tpDustHeight = texelFetch(lookSettings, ivec2(8, 67), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float tpSee = kfade(2.0 / p_tpGrain);
    float tpId, tpEdge;
    kvor(uv * p_tpGrain + seed, tpId, tpEdge);
    float tpRim = (1.0 - smoothstep(0.0, 0.18, tpEdge)) * tpSee;
    float tpCell = (kh1(tpId) - 0.5) * tpSee;
    float tpUp = smoothstep(0.2, 0.9, wn.y);
    float tpF = p_tpFade * tpUp * (0.7 + 0.3 * kfbm4(uv * 3.0 + seed));
    k.colour = mix(p_tpColour, p_tpFaded, tpF) * (1.0 + 0.12 * tpCell - 0.15 * tpRim);
    k.rough = clamp(p_tpRough + 0.1 * tpF - 0.08 * tpRim, 0.0, 1.0);
    k.height = p_tpGrainDepth * (0.6 * tpRim + 0.4 * tpCell);
    float tpLow = 1.0 - smoothstep(0.0, p_tpDustHeight, wp.y);
    float tpD = clamp(p_tpDust * tpLow * smoothstep(0.3, 0.8, kfbm(uv * 5.0 + seed + 7.0) + 0.3 * tpLow) * 1.4, 0.0, 1.0);
    k.colour = mix(k.colour, p_tpDustColour, tpD);
    k.rough = mix(k.rough, 0.9, tpD);

}

