  p_pcWindow = texelFetch(lookSettings, ivec2(5, 75), 0).r;
  p_pcRough = texelFetch(lookSettings, ivec2(6, 75), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
