void look_118(inout Look k) {
  p_glTint = texelFetch(lookSettings, ivec2(0, 118), 0).rgb;
  p_glTint2 = texelFetch(lookSettings, ivec2(1, 118), 0).rgb;
  p_glWaves = texelFetch(lookSettings, ivec2(2, 118), 0).r;
  p_glWaveDepth = texelFetch(lookSettings, ivec2(3, 118), 0).r;
  p_glSeeds = texelFetch(lookSettings, ivec2(4, 118), 0).r;
  p_glRough = texelFetch(lookSettings, ivec2(5, 118), 0).r;
  p_glAlpha = texelFetch(lookSettings, ivec2(6, 118), 0).r;
  p_glAlphaVar = texelFetch(lookSettings, ivec2(7, 118), 0).r;
  p_glRibs = texelFetch(lookSettings, ivec2(8, 118), 0).r;
  p_glRibWide = texelFetch(lookSettings, ivec2(9, 118), 0).r;
  p_glRibAlpha = texelFetch(lookSettings, ivec2(10, 118), 0).r;
  p_glGlow = texelFetch(lookSettings, ivec2(11, 118), 0).rgb;
  p_glCrease = texelFetch(lookSettings, ivec2(12, 118), 0).r;
  p_glCreaseFreq = texelFetch(lookSettings, ivec2(13, 118), 0).r;
  p_glBands = texelFetch(lookSettings, ivec2(14, 118), 0).r;
  p_glBandHigh = texelFetch(lookSettings, ivec2(15, 118), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float wave = kfbm4(uv * p_glWaves + seed);
    float seeds = smoothstep(0.08, 0.02, kcell(uv * 60.0 + seed)) * kfade(0.01);
    // the twin wall's ribs, along u, one every 1 / glRibs metres across v; under a pixel, their mean cover
    float glRib = 0.0;
    if (p_glRibs > 0.0) {
      float glRd = abs(fract(uv.y * p_glRibs) - 0.5) * 2.0;
      float glRw = fwidth(uv.y * p_glRibs) * 2.0;
      float glLine = 1.0 - smoothstep(p_glRibWide - glRw, p_glRibWide + glRw, 1.0 - glRd);
      glRib = mix(p_glRibWide, glLine, kfade(1.5 / p_glRibs));
    }
    // the film's creases and wound bands, level round the load (the world's height, and the way along the face)
    float glFold = 0.0, glBand = 0.0;
    if (p_glCrease > 0.0 || p_glBands > 0.0) {
      vec3 glSide = cross(vec3(0.0, 1.0, 0.0), wn);
      float glAlong = dot(glSide, glSide) > 0.01 ? dot(wp, normalize(glSide)) : wp.x;
      float glUp = wp.y + 0.03 * kn(vec2(glAlong * 2.0, 0.0) + seed);
      float glF = kn(vec2(glAlong * 1.6, glUp * p_glCreaseFreq) + seed * 1.7);
