void look_226(inout Look k) {
  p_apColour = texelFetch(lookSettings, ivec2(0, 226), 0).rgb;
  p_apFlake = texelFetch(lookSettings, ivec2(1, 226), 0).r;
  p_apFlakeColour = texelFetch(lookSettings, ivec2(2, 226), 0).rgb;
  p_apFlakeSize = texelFetch(lookSettings, ivec2(3, 226), 0).r;
  p_apRough = texelFetch(lookSettings, ivec2(4, 226), 0).r;
  p_apCoat = texelFetch(lookSettings, ivec2(5, 226), 0).r;
  p_apCoatRough = texelFetch(lookSettings, ivec2(6, 226), 0).r;
  p_apPeel = texelFetch(lookSettings, ivec2(7, 226), 0).r;
  p_apPeelDepth = texelFetch(lookSettings, ivec2(8, 226), 0).r;
  p_apDust = texelFetch(lookSettings, ivec2(9, 226), 0).r;
  p_apDustColour = texelFetch(lookSettings, ivec2(10, 226), 0).rgb;
  p_apDustHeight = texelFetch(lookSettings, ivec2(11, 226), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // flake: one fleck a cell, each its own brightness and its own tilt, fading to its mean where a fleck is under a pixel
    vec2 apC = floor(uv / p_apFlakeSize);
    float apS = kh(apC + seed);
    float apSee = kfade(p_apFlakeSize * 3.0);
    float apFleck = mix(0.5, step(0.55, apS) * (0.4 + 0.6 * kh(apC + seed + 17.0)), apSee) * p_apFlake;
    vec3 apBase = p_apColour * (0.97 + 0.06 * kfbm4(uv * 1.5 + seed));
    k.colour = mix(apBase, apBase * 0.4 + p_apFlakeColour * 0.6, apFleck * 0.35);
    k.metal = p_apFlake * 0.6;
    k.rough = clamp(p_apRough - 0.15 * apFleck, 0.0, 1.0);
    float apPeelF = kfade(2.0 / p_apPeel);
    float apP = (1.0 - kcell(uv * p_apPeel + seed)) * apPeelF;
    k.height = p_apPeelDepth * apP + 0.000004 * (apS - 0.5) * apSee * p_apFlake;
    k.clearcoat = p_apCoat;
    k.clearcoatRough = p_apCoatRough;
    // road dust: thick at the ground, gone by apDustHeight, broken up so it reads as spray, not a band
    float apLow = 1.0 - smoothstep(0.0, p_apDustHeight, wp.y);
    float apSpray = smoothstep(0.25, 0.85, kfbm(uv * 6.0 + seed + 3.0) + 0.35 * apLow);
    float apD = clamp(p_apDust * apLow * apSpray * 1.4, 0.0, 1.0);
    k.colour = mix(k.colour, p_apDustColour * (0.85 + 0.3 * kn(uv * 60.0 + seed)), apD);
    k.rough = mix(k.rough, 0.85, apD);
    k.metal = mix(k.metal, 0.0, apD);
    k.clearcoat = mix(k.clearcoat, 0.0, apD);

}

void look_227(inout Look k) {
  p_tpColour = texelFetch(lookSettings, ivec2(0, 227), 0).rgb;
  p_tpFaded = texelFetch(lookSettings, ivec2(1, 227), 0).rgb;
  p_tpFade = texelFetch(lookSettings, ivec2(2, 227), 0).r;
  p_tpGrain = texelFetch(lookSettings, ivec2(3, 227), 0).r;
  p_tpGrainDepth = texelFetch(lookSettings, ivec2(4, 227), 0).r;
  p_tpRough = texelFetch(lookSettings, ivec2(5, 227), 0).r;
  p_tpDust = texelFetch(lookSettings, ivec2(6, 227), 0).r;
  p_tpDustColour = texelFetch(lookSettings, ivec2(7, 227), 0).rgb;
  p_tpDustHeight = texelFetch(lookSettings, ivec2(8, 227), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float tpSee = kfade(2.0 / p_tpGrain);
    float tpId, tpEdge;
    kvor(uv * p_tpGrain + seed, tpId, tpEdge);
    float tpRim = (1.0 - smoothstep(0.0, 0.18, tpEdge)) * tpSee;
    float tpCell = (kh1(tpId) - 0.5) * tpSee;
    float tpUp = smoothstep(0.2, 0.9, wn.y);
    float tpF = p_tpFade * tpUp * (0.7 + 0.3 * kfbm4(uv * 3.0 + seed));
    k.colour = mix(p_tpColour, p_tpFaded, tpF) * (1.0 + 0.12 * tpCell - 0.15 * tpRim);
    k.rough = clamp(p_tpRough + 0.1 * tpF - 0.08 * tpRim, 0.0, 1.0);
    k.height = p_tpGrainDepth * (0.6 * tpRim + 0.4 * tpCell);
    float tpLow = 1.0 - smoothstep(0.0, p_tpDustHeight, wp.y);
    float tpD = clamp(p_tpDust * tpLow * smoothstep(0.3, 0.8, kfbm(uv * 5.0 + seed + 7.0) + 0.3 * tpLow) * 1.4, 0.0, 1.0);
    k.colour = mix(k.colour, p_tpDustColour, tpD);
    k.rough = mix(k.rough, 0.9, tpD);

}

void look_228(inout Look k) {
  p_pmColour = texelFetch(lookSettings, ivec2(0, 228), 0).rgb;
  p_pmPeel = texelFetch(lookSettings, ivec2(1, 228), 0).r;
  p_pmRelief = texelFetch(lookSettings, ivec2(2, 228), 0).r;
  p_pmRough = texelFetch(lookSettings, ivec2(3, 228), 0).r;
  p_pmCoat = texelFetch(lookSettings, ivec2(4, 228), 0).r;
  p_pmCoatRough = texelFetch(lookSettings, ivec2(5, 228), 0).r;
  p_pmOil = texelFetch(lookSettings, ivec2(6, 228), 0).r;
  p_pmOilColour = texelFetch(lookSettings, ivec2(7, 228), 0).rgb;
  p_pmOilStreaks = texelFetch(lookSettings, ivec2(8, 228), 0).r;
  p_pmOilRough = texelFetch(lookSettings, ivec2(9, 228), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float pmF = kfade(2.0 / p_pmPeel);
    float pmPeel = (1.0 - kcell(uv * p_pmPeel + seed)) * pmF;
    float pmFine = kn(uv * p_pmPeel * 2.7 + seed + 3.0) * kfade(1.0 / p_pmPeel);
    k.colour = p_pmColour * (0.985 + 0.03 * kfbm4(uv * 2.0 + seed));
    k.rough = clamp(p_pmRough + 0.04 * pmFine, 0.0, 1.0);
    k.height = p_pmRelief * (0.75 * pmPeel + 0.25 * pmFine);
    k.clearcoat = p_pmCoat;
    k.clearcoatRough = p_pmCoatRough;
    if (p_pmOil > 0.0) {
      // runs: noise drawn out along u, fine across v; blotches: a slow fbm; thick where both lie
      float pmRun = kn(vec2(uv.x * p_pmOilStreaks * 0.12, uv.y * p_pmOilStreaks) + seed + 5.0);
      float pmBlot = kfbm(uv * 2.5 + seed + 9.0);
      float pmThick = smoothstep(0.4, 0.8, 0.55 * pmRun + 0.45 * pmBlot);
      float pmO = clamp(p_pmOil * (0.15 + 0.85 * pmThick), 0.0, 1.0);
      vec3 pmOilC = p_pmOilColour * (0.7 + 0.6 * kn(vec2(uv.x * 3.0, uv.y * 40.0) + seed));
      k.colour = mix(k.colour, pmOilC, pmO);
      k.rough = mix(k.rough, p_pmOilRough + 0.5 * (1.0 - pmThick), pmO);
      k.clearcoat = mix(k.clearcoat, 0.0, pmO);
      k.height += p_pmOil * 0.00006 * pmThick;
    }

}

void look_229(inout Look k) {
  p_ucColour = texelFetch(lookSettings, ivec2(0, 229), 0).rgb;
  p_ucRough = texelFetch(lookSettings, ivec2(1, 229), 0).r;
  p_ucGrime = texelFetch(lookSettings, ivec2(2, 229), 0).r;
  p_ucGrimeColour = texelFetch(lookSettings, ivec2(3, 229), 0).rgb;
  p_ucDust = texelFetch(lookSettings, ivec2(4, 229), 0).r;
  p_ucDustColour = texelFetch(lookSettings, ivec2(5, 229), 0).rgb;
  p_ucChips = texelFetch(lookSettings, ivec2(6, 229), 0).r;
  p_ucRust = texelFetch(lookSettings, ivec2(7, 229), 0).rgb;
  p_ucOil = texelFetch(lookSettings, ivec2(8, 229), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float ucDown = smoothstep(0.0, -0.8, wn.y);
    float ucUp = smoothstep(0.3, 0.95, wn.y);
    float ucB = kfbm(uv * 4.0 + seed);
    float ucG = clamp(p_ucGrime * (0.3 + 0.9 * ucDown) * smoothstep(0.3, 0.75, ucB + 0.25 * ucDown), 0.0, 1.0);
    float ucD = clamp(p_ucDust * ucUp * smoothstep(0.35, 0.8, kfbm4(uv * 7.0 + seed + 4.0)), 0.0, 1.0);
    // chips gather in patches (a slow field) and are each a small blot (a fast one), so they cluster on a part
    float ucPatch = smoothstep(0.55, 0.8, kfbm4(uv * 1.5 + seed + 21.0));
    float ucChipN = (kn(uv * 70.0 + seed + 9.0) + 0.15 * kn(uv * 300.0 + seed)) * kfade(0.02);
    float ucChip = ucPatch * smoothstep(1.06 - 0.12 * p_ucChips, 1.1 - 0.12 * p_ucChips, ucChipN);
    float ucO = p_ucOil * smoothstep(0.55, 0.85, kfbm4(uv * 2.0 + seed + 11.0));
    k.colour = mix(p_ucColour, p_ucGrimeColour, ucG);
    k.colour = mix(k.colour, p_ucDustColour, ucD);
    k.colour = mix(k.colour, p_ucRust * (0.7 + 0.6 * kn(uv * 200.0 + seed)), ucChip);
    k.colour = mix(k.colour, vec3(0.01, 0.008, 0.006), ucO);
    k.rough = clamp(p_ucRough + 0.35 * ucG + 0.3 * ucD + 0.35 * ucChip - 0.4 * ucO, 0.05, 1.0);
    k.metal = 0.0;
    k.height = 0.00015 * ucG * ucB - 0.0001 * ucChip;

}

void look_230(inout Look k) {
  p_glTint = texelFetch(lookSettings, ivec2(0, 230), 0).rgb;
  p_glTint2 = texelFetch(lookSettings, ivec2(1, 230), 0).rgb;
  p_glWaves = texelFetch(lookSettings, ivec2(2, 230), 0).r;
  p_glWaveDepth = texelFetch(lookSettings, ivec2(3, 230), 0).r;
  p_glSeeds = texelFetch(lookSettings, ivec2(4, 230), 0).r;
  p_glRough = texelFetch(lookSettings, ivec2(5, 230), 0).r;
  p_glAlpha = texelFetch(lookSettings, ivec2(6, 230), 0).r;
  p_glAlphaVar = texelFetch(lookSettings, ivec2(7, 230), 0).r;
  p_glRibs = texelFetch(lookSettings, ivec2(8, 230), 0).r;
  p_glRibWide = texelFetch(lookSettings, ivec2(9, 230), 0).r;
  p_glRibAlpha = texelFetch(lookSettings, ivec2(10, 230), 0).r;
  p_glGlow = texelFetch(lookSettings, ivec2(11, 230), 0).rgb;
  p_glCrease = texelFetch(lookSettings, ivec2(12, 230), 0).r;
  p_glCreaseFreq = texelFetch(lookSettings, ivec2(13, 230), 0).r;
  p_glBands = texelFetch(lookSettings, ivec2(14, 230), 0).r;
  p_glBandHigh = texelFetch(lookSettings, ivec2(15, 230), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float wave = kfbm4(uv * p_glWaves + seed);
    float seeds = smoothstep(0.08, 0.02, kcell(uv * 60.0 + seed)) * kfade(0.01);
    // the twin wall's ribs, along u, one every 1 / glRibs metres across v; under a pixel, their mean cover
    float glRib = 0.0;
    if (p_glRibs > 0.0) {
      float glRd = abs(fract(uv.y * p_glRibs) - 0.5) * 2.0;
      float glRw = fwidth(uv.y * p_glRibs) * 2.0;
      float glLine = 1.0 - smoothstep(p_glRibWide - glRw, p_glRibWide + glRw, 1.0 - glRd);
      glRib = mix(p_glRibWide, glLine, kfade(1.5 / p_glRibs));
    }
    // the film's creases and wound bands, level round the load (the world's height, and the way along the face)
    float glFold = 0.0, glBand = 0.0;
    if (p_glCrease > 0.0 || p_glBands > 0.0) {
      vec3 glSide = cross(vec3(0.0, 1.0, 0.0), wn);
      float glAlong = dot(glSide, glSide) > 0.01 ? dot(wp, normalize(glSide)) : wp.x;
      float glUp = wp.y + 0.03 * kn(vec2(glAlong * 2.0, 0.0) + seed);
      float glF = kn(vec2(glAlong * 1.6, glUp * p_glCreaseFreq) + seed * 1.7);
      float glF2 = kn(vec2(glAlong * 3.1, glUp * p_glCreaseFreq * 2.3) + seed + 5.0);
      glFold = p_glCrease * mix(0.35, pow(1.0 - abs(glF * 2.0 - 1.0), 6.0) * 0.75 + pow(1.0 - abs(glF2 * 2.0 - 1.0), 8.0) * 0.4,
                                kfade(1.0 / p_glCreaseFreq));
      float glB = fract(glUp / p_glBandHigh + 0.15 * kn(vec2(glAlong * 0.8, 3.0) + seed));
      glBand = p_glBands * smoothstep(0.55, 0.62, glB) * (0.8 + 0.4 * kn(vec2(glAlong * 4.0, glUp * 6.0) + seed));
    }
    k.colour = mix(p_glTint, p_glTint2, wave) + seeds * p_glSeeds + vec3(0.12 * glRib + 0.25 * glFold + 0.06 * glBand);
    k.rough = p_glRough + p_glRough * wave;
    k.metal = 0.0;
    k.height = p_glWaveDepth * (wave - 0.5) + 0.0003 * glFold;
    k.alpha = clamp(p_glAlpha + p_glAlphaVar * wave + p_glRibAlpha * glRib + 0.35 * glFold + 0.18 * glBand, 0.0, 1.0);
    k.glow = p_glGlow * (0.9 + 0.2 * wave) * (1.0 + 0.4 * glRib);

}

void look_231(inout Look k) {
  p_pcTint = texelFetch(lookSettings, ivec2(0, 231), 0).rgb;
  p_pcSky = texelFetch(lookSettings, ivec2(1, 231), 0).rgb;
  p_pcHorizon = texelFetch(lookSettings, ivec2(2, 231), 0).rgb;
  p_pcFloor = texelFetch(lookSettings, ivec2(3, 231), 0).rgb;
  p_pcBlur = texelFetch(lookSettings, ivec2(4, 231), 0).r;
  p_pcWindow = texelFetch(lookSettings, ivec2(5, 231), 0).r;
  p_pcRough = texelFetch(lookSettings, ivec2(6, 231), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec3 pcN = normalize(wn);
    vec3 pcI = normalize(wp - cameraPosition);
    vec3 pcR = reflect(pcI, pcN);
    // how far up the reflected line points: -1 straight down, 1 straight up
    float pcUp = pcR.y;
    float pcB = p_pcBlur;
    // the floor below, the sky above, a bright band at the horizon between them
    vec3 pcEnv = mix(p_pcFloor, p_pcSky, smoothstep(-pcB, pcB, pcUp));
    pcEnv = mix(pcEnv, p_pcHorizon, exp(-pcUp * pcUp / max(0.002, pcB * pcB * 0.25)) * 0.55);
    // a soft window of light high up and toward one side, so a round part has its one bright spot
    float pcW = smoothstep(0.82, 0.97, dot(pcR, normalize(vec3(0.35, 0.85, 0.4))));
    pcEnv += vec3(p_pcWindow) * pcW;
    // the faint swirls of polishing, gone to their mean where a pixel is as wide
    float pcSw = mix(0.5, kn(uv * 900.0 + seed), kfade(0.002));
    k.colour = clamp(pcEnv * p_pcTint * (0.98 + 0.04 * pcSw), 0.0, 1.0);
    k.metal = 0.0;
    k.rough = p_pcRough;

}

void look_232(inout Look k) {
  p_trColour = texelFetch(lookSettings, ivec2(0, 232), 0).rgb;
  p_trScrub = texelFetch(lookSettings, ivec2(1, 232), 0).rgb;
  p_trDust = texelFetch(lookSettings, ivec2(2, 232), 0).rgb;
  p_trDustAmount = texelFetch(lookSettings, ivec2(3, 232), 0).r;
  p_trGrit = texelFetch(lookSettings, ivec2(4, 232), 0).r;
  p_trRelief = texelFetch(lookSettings, ivec2(5, 232), 0).r;
  p_trRough = texelFetch(lookSettings, ivec2(6, 232), 0).r;
  p_trSheen = texelFetch(lookSettings, ivec2(7, 232), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float trG = kn(uv * p_trGrit + seed) * kfade(2.0 / p_trGrit);
    float trBlot = kfbm4(uv * 8.0 + seed);
    float trD = clamp(p_trDustAmount * smoothstep(0.35, 0.85, trBlot), 0.0, 1.0);
    k.colour = mix(p_trColour, p_trScrub, 0.4 * smoothstep(0.4, 0.8, kfbm4(uv * 30.0 + seed + 2.0)));
    k.colour = mix(k.colour, p_trDust, trD) * (0.94 + 0.12 * trG);
    k.rough = clamp(p_trRough + 0.06 * trG + 0.06 * trD, 0.0, 1.0);
    k.height = p_trRelief * trG;
    k.sheen = vec3(p_trSheen) * (1.0 - trD);
    k.sheenRough = 0.5;

}

void look_233(inout Look k) {
  p_bmColour = texelFetch(lookSettings, ivec2(0, 233), 0).rgb;
  p_bmLines = texelFetch(lookSettings, ivec2(1, 233), 0).r;
  p_bmStreak = texelFetch(lookSettings, ivec2(2, 233), 0).r;
  p_bmLong = texelFetch(lookSettings, ivec2(3, 233), 0).r;
  p_bmRough = texelFetch(lookSettings, ivec2(4, 233), 0).r;
  p_bmMetal = texelFetch(lookSettings, ivec2(5, 233), 0).r;
  p_bmRelief = texelFetch(lookSettings, ivec2(6, 233), 0).r;
  p_bmMirror = texelFetch(lookSettings, ivec2(7, 233), 0).r;
  p_bmSky = texelFetch(lookSettings, ivec2(8, 233), 0).rgb;
  p_bmWall = texelFetch(lookSettings, ivec2(9, 233), 0).rgb;
  p_bmFloor = texelFetch(lookSettings, ivec2(10, 233), 0).rgb;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 bmG = dot(s3, s3) > 0.25 ? normalize(s3) : vec2(1.0, 0.0);
    // along the brushing, across it
    vec2 bmQ = vec2(dot(uv, bmG), dot(uv, vec2(-bmG.y, bmG.x)));
    // the scratches: noise stretched far along the brushing, one row a scratch, faded to its mean where a scratch is
    // under a pixel; a few deeper, longer ones over them
    float bmFine = mix(0.5, kn(vec2(bmQ.x * p_bmLong * 4.0, bmQ.y * p_bmLines) + seed), kfade(2.0 / p_bmLines));
    float bmDeep = mix(0.5, kn(vec2(bmQ.x * p_bmLong, bmQ.y * p_bmLines * 0.18) + seed + 17.0), kfade(8.0 / p_bmLines));
    float bmS = 0.75 * bmFine + 0.25 * smoothstep(0.35, 0.8, bmDeep);
    // a slow cloud of the belt's passes, so a big sheet isn't one flat grey
    float bmPass = kfbm4(vec2(bmQ.x * 0.6, bmQ.y * 7.0) + seed * 1.3);
    vec3 bmC = p_bmColour * (1.0 + p_bmStreak * (bmS - 0.5) * 0.9) * (0.94 + 0.12 * bmPass);
    k.colour = bmC;
    k.metal = p_bmMetal;
    k.rough = clamp(p_bmRough + 0.12 * (bmS - 0.5) + 0.05 * (bmPass - 0.5), 0.03, 1.0);
    k.height = p_bmRelief * (bmS - 0.5);
    // the room mirrored, smeared along the brushing: its ray tipped across the scratches by each one's slope
    vec3 bmV = normalize(wp - cameraPosition);
    vec3 bmN = normalize(wn);
    vec3 bmR = reflect(bmV, bmN);
    float bmCos = clamp(dot(-bmV, bmN), 0.0, 1.0);
    float bmFres = 0.7 + 0.3 * pow(1.0 - bmCos, 3.0);
    vec3 bmRoom = rmRoom(normalize(bmR + 0.08 * (bmS - 0.5) * vec3(1.0, 0.0, 1.0)), clamp(p_bmRough * 2.2, 0.0, 1.0), p_bmSky, p_bmWall, p_bmFloor);
    k.glow = p_bmMirror * bmRoom * bmC * bmFres * (0.85 + 0.3 * bmS);
    if (lookView > 0.5 && lookView < 1.5) k.colour = vec3(0.5 + 0.5 * bmG.x, 0.5 + 0.5 * bmG.y, 0.5);

}

void look_234(inout Look k) {
  p_pmColour = texelFetch(lookSettings, ivec2(0, 234), 0).rgb;
  p_pmPeel = texelFetch(lookSettings, ivec2(1, 234), 0).r;
  p_pmRelief = texelFetch(lookSettings, ivec2(2, 234), 0).r;
  p_pmRough = texelFetch(lookSettings, ivec2(3, 234), 0).r;
  p_pmCoat = texelFetch(lookSettings, ivec2(4, 234), 0).r;
  p_pmCoatRough = texelFetch(lookSettings, ivec2(5, 234), 0).r;
  p_pmOil = texelFetch(lookSettings, ivec2(6, 234), 0).r;
  p_pmOilColour = texelFetch(lookSettings, ivec2(7, 234), 0).rgb;
  p_pmOilStreaks = texelFetch(lookSettings, ivec2(8, 234), 0).r;
  p_pmOilRough = texelFetch(lookSettings, ivec2(9, 234), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float pmF = kfade(2.0 / p_pmPeel);
    float pmPeel = (1.0 - kcell(uv * p_pmPeel + seed)) * pmF;
    float pmFine = kn(uv * p_pmPeel * 2.7 + seed + 3.0) * kfade(1.0 / p_pmPeel);
    k.colour = p_pmColour * (0.985 + 0.03 * kfbm4(uv * 2.0 + seed));
    k.rough = clamp(p_pmRough + 0.04 * pmFine, 0.0, 1.0);
    k.height = p_pmRelief * (0.75 * pmPeel + 0.25 * pmFine);
    k.clearcoat = p_pmCoat;
    k.clearcoatRough = p_pmCoatRough;
    if (p_pmOil > 0.0) {
      // runs: noise drawn out along u, fine across v; blotches: a slow fbm; thick where both lie
      float pmRun = kn(vec2(uv.x * p_pmOilStreaks * 0.12, uv.y * p_pmOilStreaks) + seed + 5.0);
      float pmBlot = kfbm(uv * 2.5 + seed + 9.0);
      float pmThick = smoothstep(0.4, 0.8, 0.55 * pmRun + 0.45 * pmBlot);
      float pmO = clamp(p_pmOil * (0.15 + 0.85 * pmThick), 0.0, 1.0);
      vec3 pmOilC = p_pmOilColour * (0.7 + 0.6 * kn(vec2(uv.x * 3.0, uv.y * 40.0) + seed));
      k.colour = mix(k.colour, pmOilC, pmO);
      k.rough = mix(k.rough, p_pmOilRough + 0.5 * (1.0 - pmThick), pmO);
      k.clearcoat = mix(k.clearcoat, 0.0, pmO);
      k.height += p_pmOil * 0.00006 * pmThick;
    }

}

void look_235(inout Look k) {
  p_cmColour = texelFetch(lookSettings, ivec2(0, 235), 0).rgb;
  p_cmSand = texelFetch(lookSettings, ivec2(1, 235), 0).r;
  p_cmRelief = texelFetch(lookSettings, ivec2(2, 235), 0).r;
  p_cmPits = texelFetch(lookSettings, ivec2(3, 235), 0).r;
  p_cmRough = texelFetch(lookSettings, ivec2(4, 235), 0).r;
  p_cmMetal = texelFetch(lookSettings, ivec2(5, 235), 0).r;
  p_cmBloom = texelFetch(lookSettings, ivec2(6, 235), 0).r;
  p_cmBloomColour = texelFetch(lookSettings, ivec2(7, 235), 0).rgb;
  p_cmHeat = texelFetch(lookSettings, ivec2(8, 235), 0).r;
  p_cmHeatColour = texelFetch(lookSettings, ivec2(9, 235), 0).rgb;
  p_cmGrime = texelFetch(lookSettings, ivec2(10, 235), 0).r;
  p_cmGrimeColour = texelFetch(lookSettings, ivec2(11, 235), 0).rgb;
  p_cmMirror = texelFetch(lookSettings, ivec2(12, 235), 0).r;
  p_cmSky = texelFetch(lookSettings, ivec2(13, 235), 0).rgb;
  p_cmWall = texelFetch(lookSettings, ivec2(14, 235), 0).rgb;
  p_cmFloor = texelFetch(lookSettings, ivec2(15, 235), 0).rgb;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the sand's grain: fine bumps, and here and there a pit, each fading to its mean where finer than a pixel
    float cmF = kfade(2.0 / p_cmSand);
    float cmG = mix(0.5, kn(uv * p_cmSand + seed), cmF);
    float cmG2 = mix(0.5, kn(uv * p_cmSand * 0.43 + seed + 5.0), kfade(4.0 / p_cmSand));
    float cmP = p_cmPits * (1.0 - smoothstep(0.0, 0.22, kcell(uv * p_cmSand * 0.3 + seed + 3.0))) * kfade(8.0 / p_cmSand);
    // the faces that look down (wn.y below 0) carry the oil and road grime, the rest a little of it in patches
    float cmDown = smoothstep(0.15, -0.85, wn.y);
    float cmGr = clamp(p_cmGrime * (0.2 + 0.9 * cmDown) * smoothstep(0.3, 0.75, kfbm(uv * 4.5 + seed + 7.0) + 0.3 * cmDown), 0.0, 1.0);
    float cmB = p_cmBloom * smoothstep(0.45, 0.85, kfbm4(uv * 3.0 + seed + 1.0));
    float cmH = p_cmHeat * smoothstep(0.25, 0.75, kfbm4(uv * 2.2 + seed + 13.0));
    float cmS = 0.6 * cmG + 0.4 * cmG2;
    vec3 cmC = p_cmColour * (0.9 + 0.2 * cmS) * (1.0 - 0.45 * cmP);
    cmC = mix(cmC, p_cmBloomColour, cmB);
    cmC = mix(cmC, p_cmHeatColour * (0.85 + 0.3 * cmS), cmH);
    cmC = mix(cmC, p_cmGrimeColour, clamp(cmGr + 0.6 * cmP * p_cmGrime, 0.0, 1.0));
    k.colour = cmC;
    k.metal = p_cmMetal * (1.0 - 0.5 * cmB) * (1.0 - 0.8 * cmGr);
    k.rough = clamp(p_cmRough + 0.12 * (cmS - 0.5) + 0.2 * cmB + 0.25 * cmGr + 0.2 * cmP, 0.05, 1.0);
    k.height = p_cmRelief * (cmS - 0.5 - 0.9 * cmP) + 0.00003 * cmGr;
    k.ao = 1.0 - 0.35 * cmP;
    // the room mirrored softly, as a satin casting shows it, less where it is bloomed or grimed
    vec3 cmV = normalize(wp - cameraPosition);
    vec3 cmN = normalize(wn);
    float cmCos = clamp(dot(-cmV, cmN), 0.0, 1.0);
    vec3 cmRoom = rmRoom(reflect(cmV, cmN), clamp(p_cmRough * 1.8, 0.0, 1.0), p_cmSky, p_cmWall, p_cmFloor);
    k.glow = p_cmMirror * cmRoom * cmC * (0.7 + 0.3 * pow(1.0 - cmCos, 3.0)) * (1.0 - cmGr) * (1.0 - 0.5 * cmB);

}

void look_236(inout Look k) {
  p_pcTint = texelFetch(lookSettings, ivec2(0, 236), 0).rgb;
  p_pcSky = texelFetch(lookSettings, ivec2(1, 236), 0).rgb;
  p_pcHorizon = texelFetch(lookSettings, ivec2(2, 236), 0).rgb;
  p_pcFloor = texelFetch(lookSettings, ivec2(3, 236), 0).rgb;
  p_pcBlur = texelFetch(lookSettings, ivec2(4, 236), 0).r;
  p_pcWindow = texelFetch(lookSettings, ivec2(5, 236), 0).r;
  p_pcRough = texelFetch(lookSettings, ivec2(6, 236), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec3 pcN = normalize(wn);
    vec3 pcI = normalize(wp - cameraPosition);
    vec3 pcR = reflect(pcI, pcN);
    // how far up the reflected line points: -1 straight down, 1 straight up
    float pcUp = pcR.y;
    float pcB = p_pcBlur;
    // the floor below, the sky above, a bright band at the horizon between them
    vec3 pcEnv = mix(p_pcFloor, p_pcSky, smoothstep(-pcB, pcB, pcUp));
    pcEnv = mix(pcEnv, p_pcHorizon, exp(-pcUp * pcUp / max(0.002, pcB * pcB * 0.25)) * 0.55);
    // a soft window of light high up and toward one side, so a round part has its one bright spot
    float pcW = smoothstep(0.82, 0.97, dot(pcR, normalize(vec3(0.35, 0.85, 0.4))));
    pcEnv += vec3(p_pcWindow) * pcW;
    // the faint swirls of polishing, gone to their mean where a pixel is as wide
    float pcSw = mix(0.5, kn(uv * 900.0 + seed), kfade(0.002));
    k.colour = clamp(pcEnv * p_pcTint * (0.98 + 0.04 * pcSw), 0.0, 1.0);
    k.metal = 0.0;
    k.rough = p_pcRough;

}

