  p_tpGrainDepth = texelFetch(lookSettings, ivec2(4, 306), 0).r;
  p_tpRough = texelFetch(lookSettings, ivec2(5, 306), 0).r;
  p_tpDust = texelFetch(lookSettings, ivec2(6, 306), 0).r;
  p_tpDustColour = texelFetch(lookSettings, ivec2(7, 306), 0).rgb;
