  p_pmRough = texelFetch(lookSettings, ivec2(3, 307), 0).r;
  p_pmCoat = texelFetch(lookSettings, ivec2(4, 307), 0).r;
  p_pmCoatRough = texelFetch(lookSettings, ivec2(5, 307), 0).r;
