  p_pmOilColour = texelFetch(lookSettings, ivec2(7, 307), 0).rgb;
  p_pmOilStreaks = texelFetch(lookSettings, ivec2(8, 307), 0).r;
  p_pmOilRough = texelFetch(lookSettings, ivec2(9, 307), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float pmF = kfade(2.0 / p_pmPeel);
    float pmPeel = (1.0 - kcell(uv * p_pmPeel + seed)) * pmF;
    float pmFine = kn(uv * p_pmPeel * 2.7 + seed + 3.0) * kfade(1.0 / p_pmPeel);
    k.colour = p_pmColour * (0.985 + 0.03 * kfbm4(uv * 2.0 + seed));
    k.rough = clamp(p_pmRough + 0.04 * pmFine, 0.0, 1.0);
    k.height = p_pmRelief * (0.75 * pmPeel + 0.25 * pmFine);
    k.clearcoat = p_pmCoat;
    k.clearcoatRough = p_pmCoatRough;
    if (p_pmOil > 0.0) {
      // runs: noise drawn out along u, fine across v; blotches: a slow fbm; thick where both lie
      float pmRun = kn(vec2(uv.x * p_pmOilStreaks * 0.12, uv.y * p_pmOilStreaks) + seed + 5.0);
      float pmBlot = kfbm(uv * 2.5 + seed + 9.0);
      float pmThick = smoothstep(0.4, 0.8, 0.55 * pmRun + 0.45 * pmBlot);
      float pmO = clamp(p_pmOil * (0.15 + 0.85 * pmThick), 0.0, 1.0);
      vec3 pmOilC = p_pmOilColour * (0.7 + 0.6 * kn(vec2(uv.x * 3.0, uv.y * 40.0) + seed));
      k.colour = mix(k.colour, pmOilC, pmO);
      k.rough = mix(k.rough, p_pmOilRough + 0.5 * (1.0 - pmThick), pmO);
      k.clearcoat = mix(k.clearcoat, 0.0, pmO);
      k.height += p_pmOil * 0.00006 * pmThick;
    }

}

void look_308(inout Look k) {
  p_cmColour = texelFetch(lookSettings, ivec2(0, 308), 0).rgb;
  p_cmSand = texelFetch(lookSettings, ivec2(1, 308), 0).r;
  p_cmRelief = texelFetch(lookSettings, ivec2(2, 308), 0).r;
  p_cmPits = texelFetch(lookSettings, ivec2(3, 308), 0).r;
  p_cmRough = texelFetch(lookSettings, ivec2(4, 308), 0).r;
  p_cmMetal = texelFetch(lookSettings, ivec2(5, 308), 0).r;
  p_cmBloom = texelFetch(lookSettings, ivec2(6, 308), 0).r;
  p_cmBloomColour = texelFetch(lookSettings, ivec2(7, 308), 0).rgb;
  p_cmHeat = texelFetch(lookSettings, ivec2(8, 308), 0).r;
  p_cmHeatColour = texelFetch(lookSettings, ivec2(9, 308), 0).rgb;
  p_cmGrime = texelFetch(lookSettings, ivec2(10, 308), 0).r;
  p_cmGrimeColour = texelFetch(lookSettings, ivec2(11, 308), 0).rgb;
  p_cmMirror = texelFetch(lookSettings, ivec2(12, 308), 0).r;
  p_cmSky = texelFetch(lookSettings, ivec2(13, 308), 0).rgb;
  p_cmWall = texelFetch(lookSettings, ivec2(14, 308), 0).rgb;
  p_cmFloor = texelFetch(lookSettings, ivec2(15, 308), 0).rgb;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the sand's grain: fine bumps, and here and there a pit, each fading to its mean where finer than a pixel
    float cmF = kfade(2.0 / p_cmSand);
    float cmG = mix(0.5, kn(uv * p_cmSand + seed), cmF);
    float cmG2 = mix(0.5, kn(uv * p_cmSand * 0.43 + seed + 5.0), kfade(4.0 / p_cmSand));
    float cmP = p_cmPits * (1.0 - smoothstep(0.0, 0.22, kcell(uv * p_cmSand * 0.3 + seed + 3.0))) * kfade(8.0 / p_cmSand);
    // the faces that look down (wn.y below 0) carry the oil and road grime, the rest a little of it in patches
    float cmDown = smoothstep(0.15, -0.85, wn.y);
    float cmGr = clamp(p_cmGrime * (0.2 + 0.9 * cmDown) * smoothstep(0.3, 0.75, kfbm(uv * 4.5 + seed + 7.0) + 0.3 * cmDown), 0.0, 1.0);
    float cmB = p_cmBloom * smoothstep(0.45, 0.85, kfbm4(uv * 3.0 + seed + 1.0));
    float cmH = p_cmHeat * smoothstep(0.25, 0.75, kfbm4(uv * 2.2 + seed + 13.0));
    float cmS = 0.6 * cmG + 0.4 * cmG2;
    vec3 cmC = p_cmColour * (0.9 + 0.2 * cmS) * (1.0 - 0.45 * cmP);
    cmC = mix(cmC, p_cmBloomColour, cmB);
    cmC = mix(cmC, p_cmHeatColour * (0.85 + 0.3 * cmS), cmH);
    cmC = mix(cmC, p_cmGrimeColour, clamp(cmGr + 0.6 * cmP * p_cmGrime, 0.0, 1.0));
    k.colour = cmC;
    k.metal = p_cmMetal * (1.0 - 0.5 * cmB) * (1.0 - 0.8 * cmGr);
    k.rough = clamp(p_cmRough + 0.12 * (cmS - 0.5) + 0.2 * cmB + 0.25 * cmGr + 0.2 * cmP, 0.05, 1.0);
    k.height = p_cmRelief * (cmS - 0.5 - 0.9 * cmP) + 0.00003 * cmGr;
    k.ao = 1.0 - 0.35 * cmP;
    // the room mirrored softly, as a satin casting shows it, less where it is bloomed or grimed
    vec3 cmV = normalize(wp - cameraPosition);
    vec3 cmN = normalize(wn);
    float cmCos = clamp(dot(-cmV, cmN), 0.0, 1.0);
    vec3 cmRoom = rmRoom(reflect(cmV, cmN), clamp(p_cmRough * 1.8, 0.0, 1.0), p_cmSky, p_cmWall, p_cmFloor);
    k.glow = p_cmMirror * cmRoom * cmC * (0.7 + 0.3 * pow(1.0 - cmCos, 3.0)) * (1.0 - cmGr) * (1.0 - 0.5 * cmB);

}

void look_309(inout Look k) {
  p_stColour = texelFetch(lookSettings, ivec2(0, 309), 0).rgb;
  p_stMetal = texelFetch(lookSettings, ivec2(1, 309), 0).r;
  p_stRough = texelFetch(lookSettings, ivec2(2, 309), 0).r;
  p_stOil = texelFetch(lookSettings, ivec2(3, 309), 0).r;
  p_stOilColour = texelFetch(lookSettings, ivec2(4, 309), 0).rgb;
  p_stOilBrown = texelFetch(lookSettings, ivec2(5, 309), 0).rgb;
  p_stOilSize = texelFetch(lookSettings, ivec2(6, 309), 0).r;
  p_stOilRough = texelFetch(lookSettings, ivec2(7, 309), 0).r;
  p_stFinPitch = texelFetch(lookSettings, ivec2(8, 309), 0).r;
  p_stFinShare = texelFetch(lookSettings, ivec2(9, 309), 0).r;
  p_stFinDepth = texelFetch(lookSettings, ivec2(10, 309), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float brush = kn(vec2(uv.x * 4.0, uv.y * 900.0) + seed) * kfade(0.002);
    float wear = kfbm(uv * 3.0 + seed);
    vec3 stC = p_stColour * (0.9 + 0.12 * brush) * (0.9 + 0.15 * wear);
    float stM = p_stMetal;
    float stR = p_stRough + 0.15 * brush + 0.1 * wear;
    float stH = 0.00005 * brush;
    // fins: a rounded ridge of share stFinShare in each pitch along s3.x, the groove between them the depth down and
    // dark (the normal they bend is worked out below); fading to the fins' mean where a pitch is under a few pixels
    float stOn = step(0.5, s3.y);
    float stFade = kfade(p_stFinPitch * 4.0);
    float stF = fract(s3.x / p_stFinPitch);
    float stRidge = smoothstep(1.0 - 2.0 * p_stFinShare, 1.0, 0.5 + 0.5 * cos(6.28318 * stF));
    // far off, the fins' mean: the ridges' share lit, the rest groove
    float stShade = mix(p_stFinShare, stRidge, stFade);
    stC *= mix(1.0, 0.55 + 0.45 * stShade, stOn);
    // burnt castor oil: blotches and runs of a brown-black varnish; thick (glossy, brown in its highlight) or thin
    float stBlot = kfbm(uv * p_stOilSize + seed * 1.7);
    float stRun = kn(vec2(uv.x * p_stOilSize * 0.6, uv.y * p_stOilSize * 9.0) + seed + 11.0);
    float stThick = smoothstep(0.35, 0.75, 0.65 * stBlot + 0.35 * stRun);
    float stO = clamp(p_stOil * (0.75 + 0.35 * stThick), 0.0, 1.0);
    vec3 stOilC = mix(p_stOilColour, p_stOilBrown, stThick * (0.5 + 0.5 * kn(uv * 60.0 + seed)));
    stC = mix(stC, stOilC * mix(1.0, 0.6 + 0.4 * stShade, stOn), stO);
    stM = mix(stM, 0.12, stO);
    stR = mix(stR, mix(0.75, p_stOilRough, stThick), stO);
    stH += p_stOil * 0.00004 * stThick;
    k.colour = stC;
    k.metal = stM;
    k.rough = stR;
    k.height = stH;
    if (stOn > 0.5) {
      // the fins bend the normal from their profile's slope worked out exactly, not from the pixels' neighbours (whose
      // steps break thin rings into dots): the way s3.x grows across the surface, in the view's ways, from its change
      // between pixels (it is even across a face, so this is clean), times the profile's slope along it
      vec3 stN = normalize(vNormal);
      vec3 stPx = dFdx(-vViewPosition), stPy = dFdy(-vViewPosition);
      vec3 stR1 = cross(stPy, stN), stR2 = cross(stN, stPx);
      float stDet = dot(stPx, stR1);
      vec3 stG = (dFdx(s3.x) * stR1 + dFdy(s3.x) * stR2) / (abs(stDet) > 1e-14 ? stDet : 1e-14);
      float stPhi = 6.28318 * stF;
      float stA = 1.0 - 2.0 * p_stFinShare;
      float stT = clamp((0.5 + 0.5 * cos(stPhi) - stA) / (1.0 - stA), 0.0, 1.0);
      float stSlope = p_stFinDepth * 6.0 * stT * (1.0 - stT) / (1.0 - stA) * (-0.5 * sin(stPhi) * 6.28318 / p_stFinPitch);
      k.normal = normalize(stN - stFade * stSlope * stG);
      k.ownNormal = true;
    }

}

