  p_cmHeatColour = texelFetch(lookSettings, ivec2(9, 350), 0).rgb;
  p_cmGrime = texelFetch(lookSettings, ivec2(10, 350), 0).r;
  p_cmGrimeColour = texelFetch(lookSettings, ivec2(11, 350), 0).rgb;
